var e=JSON.parse('[[1101,"Кэширование можно реализовать с помощью объекта или `Map`, сохраняя данные по ключу и возвращая их при повторных запросах. Это снижает количество повторных вычислений или запросов к серверу.","Кэширование — это сохранение результатов работы для повторного использования.\\nОсновные шаги реализации:\\n\\n- Выбор структуры данных\\n\\n- `Object` или `Map` для простых случаев.\\n\\n- Логика сохранения\\nПри первом запросе результат вычисляется и сохраняется.\\n\\n- Логика получения\\nПри повторном запросе результат берется из кэша.\\n\\nПример:\\n\\nВывод:\\nРеализовать кэширование в JS можно без библиотек, используя `Map` или `Object`, что повышает производительность при повторных обращениях.","function createCache() {\\n  const cache = new Map();\\n  return function(key, computeFn) {\\n    if (cache.has(key)) {\\n      return cache.get(key);\\n    }\\n    const result = computeFn();\\n    cache.set(key, result);\\n    return result;\\n  };\\n}\\n\\nconst getData = createCache();\\n\\nconsole.log(getData(\'user\', () => ({ name: \'Alice\' })));\\nconsole.log(getData(\'user\', () => ({ name: \'Bob\' }))); // Возьмет из кэша"],[1102,"Для больших объемов данных лучше использовать `IndexedDB`, так как оно поддерживает асинхронную работу и хранение структурированных объектов. `LocalStorage` подходит для небольших объемов (до ~5 МБ) и синхронных операций.","Сравнение:\\n\\n- LocalStorage\\n\\n- Объем: ~5 МБ.\\n\\n- API: синхронный, блокирует основной поток.\\n\\n- Формат хранения: строки.\\n\\n- Подходит для небольших настроек, токенов.\\n\\n- IndexedDB\\n\\n- Объем: сотни МБ.\\n\\n- API: асинхронный, не блокирует UI.\\n\\n- Формат хранения: объекты, бинарные данные.\\n\\n- Подходит для офлайн-приложений, больших коллекций данных.\\n\\nПример работы с IndexedDB:\\n\\nВывод:\\n`IndexedDB` — выбор для больших данных и сложных структур, `LocalStorage` — для небольших и быстрых сохранений.","const request = indexedDB.open(\'myDB\', 1);\\n\\nrequest.onupgradeneeded = e => {\\n  const db = e.target.result;\\n  db.createObjectStore(\'users\', { keyPath: \'id\' });\\n};\\n\\nrequest.onsuccess = e => {\\n  const db = e.target.result;\\n  const tx = db.transaction(\'users\', \'readwrite\');\\n  tx.objectStore(\'users\').add({ id: 1, name: \'Alice\' });\\n};"],[1103,"Можно ограничивать размер кэша и удалять старые записи по принципу LRU (Least Recently Used) или по времени жизни (TTL). Также важно периодически очищать кэш.","Стратегии:\\n\\n- Ограничение размера\\n\\n- Хранить максимум N записей.\\n\\n- При превышении удалять самые старые.\\n\\n- Время жизни (TTL)\\n\\n- Каждая запись имеет срок действия.\\n\\n- Удаление устаревших данных при обращении.\\n\\n- Очистка по событиям\\n\\n- Очищать кэш при изменении версии приложения.\\n\\nПример LRU-кэша:\\n\\nВывод:\\nКонтроль размера и времени жизни кэша предотвращает его переполнение и повышает эффективность.","class LRUCache {\\n  constructor(limit) {\\n    this.limit = limit;\\n    this.map = new Map();\\n  }\\n  get(key) {\\n    if (!this.map.has(key)) return null;\\n    const value = this.map.get(key);\\n    this.map.delete(key);\\n    this.map.set(key, value);\\n    return value;\\n  }\\n  set(key, value) {\\n    if (this.map.size >= this.limit) {\\n      const oldest = this.map.keys().next().value;\\n      this.map.delete(oldest);\\n    }\\n    this.map.set(key, value);\\n  }\\n}"],[1104,"Метод `map` создает новый массив, применяя переданную функцию к каждому элементу исходного массива. Реализовать его можно с помощью цикла.","Метод `map` в JavaScript:\\n\\n- Не изменяет исходный массив.\\n\\n- Возвращает новый массив такой же длины.\\n\\n- Вызывает колбэк для каждого элемента.\\n\\nПример реализации:\\n\\nВывод:\\n`map` удобен для преобразования массивов, а его реализация показывает понимание принципов работы методов высшего порядка.","function myMap(array, callback) {\\n  const result = [];\\n  for (let i = 0; i < array.length; i++) {\\n    result.push(callback(array[i], i, array));\\n  }\\n  return result;\\n}\\n\\n// Использование\\nconst nums = [1, 2, 3];\\nconst doubled = myMap(nums, x => x * 2);\\nconsole.log(doubled); // [2, 4, 6]"],[1105,"Принцип подстановки Лисков гласит, что любой дочерний класс должен корректно заменять родительский, не нарушая работу программы. В React это означает, что компонент, расширяющий или заменяющий другой, должен полностью сохранять его контракт (пропсы, поведение), чтобы не ломать логику приложения.","Принцип подстановки Лисков (Liskov Substitution Principle, LSP) — одна из частей SOLID, формулируется так:\\nОбъекты дочерних классов должны быть взаимозаменяемы с объектами базового класса без нарушения корректности программы.\\nПрименение в React:\\n\\n- Контракт пропсов\\n\\n- Новый компонент, заменяющий старый, должен принимать те же обязательные пропсы и интерпретировать их одинаково.\\n\\n- Поведение\\n\\n- Замена не должна менять ожидаемое поведение для остальной системы.\\n\\n- Пример\\n\\nНарушение LSP:\\n\\n- Новый компонент требует дополнительные обязательные пропсы, которые родитель не требовал.\\n\\n- Новый компонент меняет смысл уже существующих пропсов.\\n\\nВывод:\\nВо фронтенде LSP помогает проектировать переиспользуемые и заменяемые компоненты, что особенно важно для больших проектов с длительной поддержкой.","function Button({ onClick, label }) {\\n  return <button onClick={onClick}>{label}</button>;\\n}\\n\\nfunction IconButton(props) {\\n  return <Button {...props} />;\\n}\\n// IconButton можно подставить вместо Button — контракт соблюден"],[1106,"Структура приложения должна обеспечивать единичную ответственность модулей, слабую связанность, возможность подмены реализаций и легкость расширения. В React это достигается разделением UI-компонентов, бизнес-логики и инфраструктуры.","SOLID в фронтенде:\\n\\n- S — Single Responsibility\\n\\n- Один компонент = одна ответственность.\\n\\n- UI-компонент не должен содержать бизнес-логику.\\n\\n- O — Open/Closed\\n\\n- Новое поведение добавляется расширением, а не изменением существующего кода.\\n\\n- Пример: добавление новых страниц через роутер, а не переписывание App.js.\\n\\n- L — Liskov Substitution\\n\\n- Компоненты и функции можно заменять без изменения остального кода.\\n\\n- I — Interface Segregation\\n\\n- Не перегружать компоненты пропсами, которые им не нужны.\\n\\n- D — Dependency Inversion\\n\\n- Компоненты зависят от абстракций, а не от конкретных реализаций.\\n\\nПример структуры:\\n\\nВывод:\\nПрименение SOLID во фронтенде повышает читаемость, тестируемость и масштабируемость приложения.","src/\\n  components/   // UI-компоненты\\n  hooks/        // Логика состояний\\n  services/     // API, хранилища\\n  pages/        // Страницы\\n  store/        // State-менеджмент"],[1107,"Основные проблемы — сложность синхронизации зависимостей, управление версиями, изоляция стилей, обмен состоянием и интеграция разных технологий.","Основные сложности:\\n\\n- Версионный конфликт зависимостей\\n\\n- Разные микрофронты могут использовать разные версии React или библиотек.\\n\\n- Изоляция стилей\\n\\n- Возможны конфликты CSS при глобальных стилях.\\n\\n- Производительность\\n\\n- Загрузка одинаковых библиотек в каждом микрофронте.\\n\\n- Обмен состоянием\\n\\n- Необходимость общей шины данных или синхронизации событий.\\n\\n- Сборка и деплой\\n\\n- Разный пайплайн CI/CD для каждого микрофронта.\\n\\nВывод:\\nМикрофронтенды дают гибкость, но усложняют архитектуру и требуют строгой дисциплины в управлении зависимостями и стилями.",null],[1108,"Обычно используют единый реестр версий или загрузку общих зависимостей через CDN/module federation. Важно избегать дублирования больших библиотек в каждом микрофронте.","Подходы:\\n\\n- Shared dependencies\\n\\n- В Module Federation (Webpack 5) можно вынести React как `shared`.\\n\\n- CDN\\n\\n- Загрузка зависимостей глобально и использование их в каждом микрофронте.\\n\\n- Monorepo\\n\\n- Общая кодовая база с единым `package.json`.\\n\\n- Lock-файлы\\n\\n- Единый lock-файл для всех микрофронтов.\\n\\nПример Module Federation:\\n\\nВывод:\\nЕдиная версия зависимостей снижает вес бандлов и предотвращает баги из-за несовместимости API.","// host webpack config\\nshared: {\\n  react: { singleton: true, requiredVersion: \'^18.0.0\' },\\n  \'react-dom\': { singleton: true }\\n}"],[1109,"Изоляция достигается через отдельные бандлы, scoped CSS, namespace для глобальных объектов и использование Shadow DOM при необходимости.","Способы изоляции:\\n\\n- CSS-модули или CSS-in-JS\\n\\n- Генерация уникальных классов.\\n\\n- Shadow DOM\\n\\n- Полная изоляция стилей внутри Web Component.\\n\\n- Module Federation / iframe\\n\\n- Полная загрузка приложения с собственным окружением.\\n\\n- Namespace\\n\\n- Разделение глобальных переменных.\\n\\nПример CSS-модулей:\\n\\nВывод:\\nИзоляция предотвращает конфликты между микрофронтами и делает систему более устойчивой.","/* Button.module.css */\\n.button {\\n  background: red;\\n}\\n\\nimport styles from \'./Button.module.css\';\\n<button className={styles.button}>Click</button>"],[1110,"Функция высшего порядка:\\n\\n- Принимает другую функцию как аргумент.\\n\\n- Возвращает функцию.\\nПримеры: `map`, `filter`, `setTimeout`.","Функции высшего порядка позволяют абстрагировать операции.\\nПример 1: Принимает функцию\\n\\nПример 2: Возвращает функцию\\n\\nГде применяется:\\n\\n- Обработка массивов (`map`, `filter`).\\n\\n- Асинхронные операции (`setTimeout`).\\n\\n- Замыкания.\\n\\nВывод:\\nФункции высшего порядка делают код гибким и переиспользуемым.","function greet(name, callback) {\\n  console.log(`Hello, ${name}!`);\\n  callback();\\n}\\n\\ngreet(\\"Alice\\", () => console.log(\\"Callback called!\\"));\\n\\nfunction multiplier(factor) {\\n  return function(number) {\\n    return number * factor;\\n  };\\n}\\n\\nconst double = multiplier(2);\\nconsole.log(double(5)); // 10"],[1111,"- GET — получает данные (параметры в URL, кэшируется).\\n\\n- POST — отправляет данные (тело запроса, не кэшируется).\\n\\n- GET менее безопасен, POST — для изменения данных.","1. GET:\\n\\n- Используется для чтения данных.\\n\\n- Параметры передаются в URL (`?key=value`).\\n\\n- Ограничен по длине (зависит от браузера).\\n\\n- Пример:\\n\\n2. POST:\\n\\n- Используется для отправки данных (логины, формы).\\n\\n- Данные в теле запроса (не видны в URL).\\n\\n- Нет ограничения по длине.\\n\\n- Пример:\\n\\nКогда использовать:\\n\\n- GET — для безопасных запросов (поиск, фильтрация).\\n\\n- POST — для создания/изменения данных.\\n\\nВывод:\\nВыбор метода зависит от типа операции.","fetch(\'/api/users?id=1\');\\n\\nfetch(\'/api/users\', {\\n  method: \'POST\',\\n  body: JSON.stringify({ name: \'Alice\' })\\n});"],[1112,"- Прокси-сервер (на бэкенде).\\n\\n- JSONP (устаревший способ).\\n\\n- Настройка CORS на сервере (`Access-Control-Allow-Origin`).\\n\\n- Использование расширений для разработчиков (только для теста).","1. Прокси-сервер:\\n\\n- Запрос идет через ваш сервер, который не имеет ограничений CORS.\\n\\n- Пример:\\n\\n2. JSONP:\\n\\n- Работает только для GET-запросов.\\n\\n- Пример:\\n\\n3. Настройка сервера:\\n\\n- Добавьте заголовки:\\n\\nВывод:\\nЛучший способ — настройка CORS на сервере или прокси.","// Ваш бэкенд делает запрос к чужому API\\nfetch(\'/your-proxy?url=https://external-api.com/data\');\\n\\nfunction handleResponse(data) {\\n  console.log(data);\\n}\\nconst script = document.createElement(\'script\');\\nscript.src = \'https://external-api.com/data?callback=handleResponse\';\\ndocument.body.appendChild(script);\\n\\nAccess-Control-Allow-Origin: *"],[1113,"Ссылочный тип — это объекты (включая массивы и функции), которые передаются по ссылке, а не по значению. Изменение копии изменяет оригинал.","Пример:\\n\\nКак избежать проблем:\\n\\n- Используйте `Object.assign` или спред-оператор для копирования:\\n\\nВывод:\\nОбъекты передаются по ссылке, примитивы — по значению.","const a = { value: 1 };\\nconst b = a; // b ссылается на тот же объект\\nb.value = 2;\\nconsole.log(a.value); // 2 (оригинал изменился)\\n\\nconst a = { value: 1 };\\nconst b = { ...a }; // Копия\\nb.value = 2;\\nconsole.log(a.value); // 1 (оригинал не изменился)"],[1114,"- Каррирование:\\n\\n`function add(a) {\\nreturn function(b) { return a + b; };\\n}`\\n\\n- Добавление метода в прототип числа:\\n\\n`Number.prototype.add = function(b) { return this + b; };`","1. Каррирование:\\nФункция возвращает функцию, пока не получит все аргументы.\\n\\n2. Расширение прототипа:\\n\\nВывод:\\nКаррирование полезно для частичного применения функций. Расширять прототипы следует осторожно.","function add(a) {\\n  return function(b) {\\n    return a + b;\\n  };\\n}\\nconsole.log(add(1)(2)); // 3\\n\\nNumber.prototype.add = function(b) {\\n  return this + b;\\n};\\nconsole.log((5).add(3)); // 8"],[1115,"Стрелочные функции не имеют своего `this` — они берут его из внешнего контекста. Поэтому они не подходят для методов объекта или конструкторов.","Пример проблемы:\\n\\nРешение:\\nИспользуйте обычные функции для методов:\\n\\nГде полезны стрелочные функции:\\n\\n- Колбэки (сохраняют контекст):\\n\\nВывод:\\nСтрелочные функции удобны для колбэков, но не для методов.","const obj = {\\n  value: 10,\\n  print: () => console.log(this.value) // undefined (this — глобальный объект)\\n};\\nobj.print();\\n\\nconst obj = {\\n  value: 10,\\n  print() { console.log(this.value); } // 10\\n};\\n\\nsetTimeout(() => console.log(this), 1000);"],[1116,"В обычных функциях `this` внутри `setInterval`/`setTimeout` теряется (становится `window`/`undefined` в strict mode). Стрелочные функции сохраняют `this` из внешнего контекста.","Пример проблемы:\\n\\nРешение 1: Стрелочная функция\\n\\nРешение 2: Привязка контекста\\n\\nВывод:\\nСтрелочные функции или `bind` помогают сохранить `this`.","const obj = {\\n  value: 10,\\n  print() {\\n    setTimeout(function() {\\n      console.log(this.value); // undefined (this — глобальный объект)\\n    }, 1000);\\n  }\\n};\\nobj.print();\\n\\nconst obj = {\\n  value: 10,\\n  print() {\\n    setTimeout(() => console.log(this.value), 1000); // 10\\n  }\\n};\\n\\nsetTimeout(function() { console.log(this.value); }.bind(obj), 1000);"],[1117,"`var` имеет функциональную область видимости, а не блочную. В цикле все итерации используют одну и ту же переменную, поэтому в замыканиях получается последнее значение.","Пример проблемы:\\n\\nРешение 1: `let` (блочная область видимости)\\n\\nРешение 2: Замыкание\\n\\nВывод:\\n`let` и `const` решают проблему, так как имеют блочную область видимости.","for (var i = 0; i < 3; i++) {\\n  setTimeout(() => console.log(i), 1000); // 3, 3, 3\\n}\\n\\nfor (let i = 0; i < 3; i++) {\\n  setTimeout(() => console.log(i), 1000); // 0, 1, 2\\n}\\n\\nfor (var i = 0; i < 3; i++) {\\n  (function(j) {\\n    setTimeout(() => console.log(j), 1000); // 0, 1, 2\\n  })(i);\\n}"],[1118,"- `map` создает новый массив, применяя функцию к каждому элементу исходного.\\n\\n- `filter` создает новый массив, оставляя только элементы, удовлетворяющие условию.\\n\\n- Оба метода не изменяют исходный массив (чистые функции).","1. `map`:\\n\\n- Принимает функцию-колбэк, которая преобразует каждый элемент.\\n\\n- Возвращает новый массив той же длины.\\n\\n2. `filter`:\\n\\n- Колбэк возвращает `true`/`false` для каждого элемента.\\n\\n- В новый массив попадают только элементы, где `true`.\\n\\nИсходный массив:\\n\\nВывод:\\n`map` и `filter` возвращают новые массивы, исходные данные остаются неизменными.","const numbers = [1, 2, 3];\\nconst doubled = numbers.map(x => x * 2); // [2, 4, 6]\\n\\nconst evens = numbers.filter(x => x % 2 === 0); // [2]\\n\\nconsole.log(numbers); // [1, 2, 3] (не изменился)"],[1119,"Если ни один элемент не проходит условие, `filter` вернет пустой массив (`[]`).","Пример:\\n\\nПочему не `null` или `undefined`?\\n\\n- Это согласуется с логикой работы методов массивов: всегда возвращается массив.\\n\\n- Пустой массив — валидный результат, с которым можно продолжать работу (например, вызывать другие методы).\\n\\nВывод:\\n`filter` всегда возвращает массив, даже пустой.","const numbers = [1, 3, 5];\\nconst evens = numbers.filter(x => x % 2 === 0); // []"],[1120,"- Примитивы: `number`, `string`, `boolean`, `null`, `undefined`, `symbol`, `bigint`. Хранятся по значению.\\n\\n- Ссылочные: `object`, `array`, `function`. Хранятся по ссылке.","1. Примитивы:\\n\\n- Копируются по значению.\\n\\n- Неизменяемы (например, строки).\\n\\n2. Ссылочные типы:\\n\\n- Копируется ссылка на объект.\\n\\n- Изменяемы.\\n\\nВывод:\\nПримитивы работают по значению, ссылочные типы — по ссылке.","let a = 5;\\nlet b = a; // Копируется значение\\nb = 10;\\nconsole.log(a); // 5 (не изменилось)\\n\\nlet obj1 = { name: \'Alice\' };\\nlet obj2 = obj1; // Копируется ссылка\\nobj2.name = \'Bob\';\\nconsole.log(obj1.name); // \'Bob\' (оригинал изменился)"],[1121,"Промис может быть в одном из трех состояний:\\n\\n- `pending` — ожидание.\\n\\n- `fulfilled` — успешно выполнен.\\n\\n- `rejected` — выполнен с ошибкой.","1. `pending`:\\n\\n- Начальное состояние, пока промис не завершен.\\n\\n2. `fulfilled`:\\n\\n- Промис завершился успешно (вызван `resolve`).\\n\\n3. `rejected`:\\n\\n- Промис завершился с ошибкой (вызван `reject`).\\n\\nПример:\\n\\nВывод:\\nПромис переходит из `pending` в `fulfilled` или `rejected` единожды.","const promise = new Promise((resolve, reject) => {\\n  setTimeout(() => resolve(\'Done!\'), 1000);\\n});\\n\\npromise\\n  .then(result => console.log(result)) // \'Done!\'\\n  .catch(error => console.error(error));"],[1122,"Второй аргумент `then` — это аналог `catch`:\\n\\n`promise.then(\\nresult => console.log(result),\\nerror => console.error(error) // Обработка ошибки\\n);`","Сравнение с `catch`:\\n\\nРазличие:\\n\\n- `catch` перехватывает ошибки из всех предыдущих `then`.\\n\\n- Второй аргумент `then` — только ошибки текущего промиса.\\n\\nВывод:\\nОба способа работают, но `catch` обычно предпочтительнее для цепочки промисов.","// Вариант 1: catch\\npromise\\n  .then(result => console.log(result))\\n  .catch(error => console.error(error));\\n\\n// Вариант 2: then с двумя аргументами\\npromise.then(\\n  result => console.log(result),\\n  error => console.error(error)\\n);"],[1123,"Используйте `IntersectionObserver` для эффективного отслеживания видимости. Альтернативно — сравнение координат элемента с размерами viewport.","1. IntersectionObserver (современный способ):\\n\\n2. Проверка координат (устаревший способ):\\n\\nВывод:\\n`IntersectionObserver` — предпочтительный метод из-за производительности и простоты.","const observer = new IntersectionObserver((entries) => {\\n  entries.forEach(entry => {\\n    if (entry.isIntersecting) {\\n      console.log(\'Элемент в зоне видимости\');\\n    }\\n  });\\n});\\n\\nobserver.observe(document.querySelector(\'.element\'));\\n\\nfunction isInViewport(element) {\\n  const rect = element.getBoundingClientRect();\\n  return (\\n    rect.top >= 0 &&\\n    rect.left >= 0 &&\\n    rect.bottom <= window.innerHeight &&\\n    rect.right <= window.innerWidth\\n  );\\n}"],[1124,"Выбор зависит от задачи:\\n\\n- UI-библиотеки (Material UI, Bootstrap) — для быстрой разработки и стандартных компонентов.\\n\\n- Кастомный CSS — для уникального дизайна и полного контроля.","Плюсы UI-библиотек:\\n\\n- Готовые компоненты (кнопки, формы).\\n\\n- Адаптивность \\"из коробки\\".\\n\\n- Согласованный дизайн.\\n\\nМинусы:\\n\\n- Ограниченная кастомизация.\\n\\n- Лишний код, если используются не все компоненты.\\n\\nКогда писать CSS самому:\\n\\n- Нестандартный дизайн.\\n\\n- Необходимость оптимизации (минимальный bundle).\\n\\n- Проекты с жесткими требованиями к производительности.\\n\\nПримеры:\\n\\n- Библиотеки: Material UI, Ant Design, Bootstrap.\\n\\n- Кастомный CSS: Tailwind (утилитарный подход), Sass.\\n\\nВывод:\\nДля MVP или корпоративных продуктов — библиотеки. Для уникальных интерфейсов — кастомный CSS.",null],[1125,"Сначала выполняется `&&` (логическое И), затем `||` (логическое ИЛИ). Порядок:\\n\\n- Вычисляется `B && C`.\\n\\n- Результат сравнивается с `A` через `||`.","Приоритет операторов:\\n\\n- `&&` имеет приоритет выше, чем `||` (как умножение перед сложением в математике).\\n\\nПример:\\n\\nКак работает:\\n\\n- Если `B && C` равно `true`, то `result = A || true` → вернет `A` (если `A` — truthy) или `true`.\\n\\n- Если `B && C` равно `false`, то `result = A || false` → вернет `A`.\\n\\nВывод:\\nИспользуйте скобки для явного задания порядка: `(A || B) && C` или `A || (B && C)`","const result = A || B && C;\\n// Аналогично:\\nconst temp = B && C;\\nconst result = A || temp;"],[1126,"`async/await` делает асинхронный код:\\n\\n- Читаемым (похож на синхронный).\\n\\n- Удобным для отладки (стек вызовов не «разрывается»).\\n\\n- Лёгким в обработке ошибок (через `try/catch`).","Сравнение стилей:\\n\\n- Promise:\\n\\n- async/await:\\n\\nПреимущества async/await:\\n\\n- Нет «адской» вложенности (`then` внутри `then`).\\n\\n- Ошибки ловятся стандартным `try/catch`.\\n\\n- Упрощает работу с циклами (`for`, `map`).\\n\\nКогда использовать Promises:\\n\\n- Параллельные запросы через `Promise.all()`.\\n\\n- Работа с библиотеками, которые возвращают Promise.\\n\\nВывод:\\n`async/await` — это синтаксический сахар над Promise, который делает код чище.","fetchData()\\n  .then(data => process(data))\\n  .catch(error => console.error(error));\\n\\ntry {\\n  const data = await fetchData();\\n  process(data);\\n} catch (error) {\\n  console.error(error);\\n}"],[1127,"Используйте метод `addEventListener` для подписки на событие `click`:\\n\\n`document.querySelector(\'button\').addEventListener(\'click\', () => {\\nconsole.log(\'Кнопка нажата!\');\\n});`","Способы подписки:\\n\\n- Через `addEventListener` (рекомендуемый способ):\\n\\n- Через атрибут HTML (устаревший метод):\\n\\nОсобенности:\\n\\n- `addEventListener` позволяет добавить несколько обработчиков на одно событие.\\n\\n- Для удаления обработчика используйте `removeEventListener`.\\n\\nВывод:\\nВсегда предпочитайте `addEventListener` для гибкости и лучшей поддержки кода.","const button = document.getElementById(\'myButton\');\\nbutton.addEventListener(\'click\', handleClick);\\nfunction handleClick() {\\n  alert(\'Клик!\');\\n}\\n\\n<button onclick=\\"alert(\'Клик!\')\\">Нажми меня</button>"],[1128,"Передайте третий аргумент `true` в `addEventListener` для подписки на фазу погружения (capture phase):\\n\\n`element.addEventListener(\'click\', handler, true);`","Фазы события:\\n\\n- Погружение (Capture): Событие идет сверху вниз (от `window` к целевому элементу).\\n\\n- Цель (Target): Событие достигло элемента.\\n\\n- Всплытие (Bubble): Событие поднимается вверх (по умолчанию).\\n\\nПример:\\n\\nВывод:\\nФаза погружения полезна для перехвата событий до достижения целевого элемента (например, для модальных окон).","document.querySelector(\'div\').addEventListener(\'click\', () => {\\n  console.log(\'Погружение (Capture)\');\\n}, true);\\n\\ndocument.querySelector(\'button\').addEventListener(\'click\', () => {\\n  console.log(\'Всплытие (Bubble)\');\\n});"],[1129,"Добавьте заголовки в ответ сервера:\\n\\n`Access-Control-Allow-Origin: *\\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\\nAccess-Control-Allow-Headers: Content-Type`","Минимальная настройка (Node.js пример):\\n\\nДля запросов с куки/авторизацией:\\n\\nВывод:\\nCORS настраивается на сервере. Используйте `*` для разработки, но ограничивайте домены в продакшене.","app.use((req, res, next) => {\\n  res.setHeader(\'Access-Control-Allow-Origin\', \'*\'); // Или конкретный домен\\n  res.setHeader(\'Access-Control-Allow-Methods\', \'GET, POST, OPTIONS\');\\n  res.setHeader(\'Access-Control-Allow-Headers\', \'Content-Type, Authorization\');\\n  next();\\n});\\n\\nAccess-Control-Allow-Origin: https://yourdomain.com\\nAccess-Control-Allow-Credentials: true"],[1130,"- Хранение: В браузере (посмотреть можно в DevTools → Application → Cookies).\\n\\n- Передача: Автоматически прикрепляются к HTTP-запросам в заголовке `Cookie`.","1. Установка куки (сервер):\\n\\n2. Установка куки (JavaScript):\\n\\n3. Чтение куки:\\n\\nОсобенности:\\n\\n- Куки привязываются к домену/пути.\\n\\n- Максимальный размер — ~4 КБ на домен.\\n\\nВывод:\\nКуки — это простой способ хранения данных между запросами, но для больших данных используйте `localStorage`.","Set-Cookie: sessionId=abc123; Path=/; HttpOnly; Secure\\n\\ndocument.cookie = \\"username=John; expires=Thu, 18 Dec 2025 12:00:00 UTC; path=/\\";\\n\\nconsole.log(document.cookie); // \\"username=John; sessionId=abc123\\""],[1131,"Основные флаги:\\n\\n- `HttpOnly`: Запрещает доступ к куки через JavaScript (защита от XSS).\\n\\n- `Secure`: Передача только по HTTPS.\\n\\n- `SameSite`: Защита от CSRF (`Strict`, `Lax`, `None`).\\n\\n- `Expires`/`Max-Age`: Время жизни куки.","Пример безопасной куки:\\n\\nНазначение флагов:\\n\\n- `HttpOnly`: Нельзя украсть через `document.cookie`.\\n\\n- `Secure`: Куки не уйдут по HTTP (только HTTPS).\\n\\n- `SameSite=Strict`: Куки не отправятся при переходе с другого сайта.\\n\\nВывод:\\nВсегда используйте `HttpOnly` и `Secure` для критичных данных (например, токенов).","Set-Cookie: token=xyz; Secure; HttpOnly; SameSite=Strict; Path=/"],[1132,"Access token хранится в памяти или LocalStorage для доступа к API. Refresh token хранится в HttpOnly cookie для безопасного обновления. Токен автоматически добавляется в заголовки запросов и обновляется при истечении.","Схема работы:\\n\\n- Пользователь вводит credentials\\n\\n- Сервер возвращает access и refresh tokens\\n\\n- Access token хранится в клиенте\\n\\n- Refresh token хранится в HttpOnly cookie\\n\\n- При истечении access token автоматически обновляется\\n\\nБезопасное хранение:\\n\\n- Access token: localStorage или memory\\n\\n- Refresh token: HttpOnly cookie\\n\\n- Защита от CSRF и XSS атак\\n\\nАвтоматическое обновление:\\n\\nBest practices:\\n\\n- Короткое время жизни access token\\n\\n- Secure и HttpOnly флаги для cookies\\n\\n- Валидация токенов на сервере\\n\\n- Защита от replay attacks","// Интерцептор для axios\\naxios.interceptors.response.use(\\n  response => response,\\n  async error => {\\n    if (error.response.status === 401) {\\n      const newToken = await refreshToken();\\n      // Повтор запроса с новым токеном\\n    }\\n    return Promise.reject(error);\\n  }\\n);"],[1133,"Для интеграции карт используйте JavaScript API картографических сервисов (Google Maps, Yandex Maps, Leaflet). Инициализируйте карту в компоненте, добавьте маркеры и обработчики событий.","Популярные решения:\\n\\n- Google Maps JavaScript API\\n\\n- Yandex Maps API\\n\\n- Leaflet (open-source)\\n\\n- Mapbox GL JS\\n\\nБазовая интеграция:\\n\\nReact-интеграция:\\nИспользуйте библиотеки-обертки:\\n\\n- `@react-google-maps/api`\\n\\n- `react-yandex-maps`\\n\\n- `react-leaflet`\\n\\nКлючевые функции:\\n\\n- Добавление маркеров\\n\\n- Рисование фигур и зон\\n\\n- Геокодирование адресов\\n\\n- Маршрутизация и направления\\n\\n- Кастомные стили карт\\n\\nОптимизация:\\n\\n- Ленивая загрузка карт\\n\\n- Кластеризация маркеров\\n\\n- Оптимизация производительности\\n\\n- Кэширование запросов","<div id=\\"map\\" style=\\"width: 100%; height: 400px;\\"></div>\\n\\n<script>\\n  const map = new google.maps.Map(document.getElementById(\'map\'), {\\n    center: { lat: 55.76, lng: 37.64 },\\n    zoom: 10\\n  });\\n  \\n  new google.maps.Marker({\\n    position: { lat: 55.76, lng: 37.64 },\\n    map: map,\\n    title: \'Hello World!\'\\n  });\\n<\/script>"],[1134,"Для рисования в вебе используйте Canvas API для пиксельной графики или SVG для векторной. Популярные библиотеки: D3.js для сложных визуализаций, Fabric.js для интерактивных рисунков, Three.js для 3D-графики.","Технологии рисования:\\n\\n- Canvas: пиксельная графика, высокая производительность\\n\\n- SVG: векторная графика, масштабирование без потерь\\n\\n- WebGL: 3D-графика через Canvas\\n\\nПопулярные библиотеки:\\n\\n- D3.js: сложные data visualizations\\n\\n- Fabric.js: интерактивные рисунки и редакторы\\n\\n- Three.js: 3D-графика и анимации\\n\\n- Konva.js: 2D-графика для React\\n\\nПример использования Canvas:\\n\\nReact-интеграция:\\n\\nПрименение:\\n\\n- Дашборды и аналитика\\n\\n- Графические редакторы\\n\\n- Интерактивные инфографики\\n\\n- Игры и симуляции\\n\\nBest practices:\\n\\n- Оптимизация производительности\\n\\n- Адаптивность под разные устройства\\n\\n- Доступность для пользователей\\n\\n- Кэширование сложных вычислений","const canvas = document.getElementById(\'myCanvas\');\\nconst ctx = canvas.getContext(\'2d\');\\n\\nctx.fillStyle = \'red\';\\nctx.fillRect(10, 10, 100, 100);\\n\\nimport { Stage, Layer, Circle } from \'react-konva\';\\n\\nfunction DrawingApp() {\\n  return (\\n    <Stage width={window.innerWidth} height={window.innerHeight}>\\n      <Layer>\\n        <Circle x={100} y={100} radius={50} fill=ed\\" />\\n      </Layer>\\n    </Stage>\\n  );\\n}"],[1135,"Reflow происходит, когда меняется структура страницы или размеры элементов, и браузеру нужно пересчитать расположение. Repaint вызывается, когда меняется внешний вид (например, цвет), но размеры остаются прежними. Частые reflow замедляют работу страницы, поэтому их стараются минимизировать — например, группируя изменения в DOM или используя `classList`, а не менять стили по одному.","Что такое Reflow и Repaint\\n\\n- Reflow — это перерасчет геометрии элементов: размеров, позиций, структуры. Например, при изменении ширины блока или добавлении нового элемента.\\n\\n- Repaint — это перерисовка внешнего вида без пересчета позиций. Например, смена фона или цвета текста.\\n\\nДействия, вызывающие Reflow\\n\\n- Изменение размеров элемента (`width`, `height`, `margin`, `padding`).\\n\\n- Добавление или удаление узлов в DOM.\\n\\n- Использование методов вроде `offsetWidth`, `getComputedStyle` (они вынуждают браузер вычислить актуальное состояние).\\n\\n- Изменение шрифтов, контента текста.\\n\\nКак избегать частых Reflow\\n\\n- Группировать несколько изменений сразу:\\n\\n- Использовать `classList.add/remove`, а не менять каждый стиль отдельно.\\n\\n- Работать с элементом вне DOM (через `documentFragment`) и потом вставлять целиком.\\n\\n- Использовать `requestAnimationFrame` для анимаций.\\n\\nВывод\\nReflow — дорогая операция, и его стоит минимизировать при работе с динамическим контентом. Чем меньше браузеру приходится пересчитывать расположение элементов, тем быстрее работает страница.","element.style.cssText = \\"width: 100px; height: 100px; color: red;\\";"],[1136,"Глубокое копирование можно реализовать с помощью рекурсивной функции, которая вручную создает новый объект или массив и копирует все его свойства. Для каждого свойства, если оно является объектом, функция вызывает сама себя. Основные сложности: обработка циклических ссылок (когда объект ссылается сам на себя), копирование специальных объектов (как Date, Map, Set) и поддержка различных типов данных.","Реализация глубокого копирования \\"вручную\\" требует тщательного обхода всех свойств исходного объекта и правильного копирования каждого значения.\\nБазовая реализация рекурсивной функции:\\n\\nСложности, которые могут возникнуть:\\n\\n- Циклические ссылки: Если объект A ссылается на объект B, а B ссылается на A, наивная рекурсивная функция войдет в бесконечный цикл и вызовет переполнение стека. Для решения этой проблемы используется структура данных `WeakMap` для запоминания уже скопированных объектов.\\n\\n- \\"Хрупкие\\" объекты: Некоторые объекты, like `Date`, `Map`, `Set`, `RegExp`, при простом копировании свойств потеряют свою внутреннюю структуру и функциональность. Их нужно создавать заново с помощью их конструкторов.\\n\\n- Производительность: Рекурсивный обход больших и сложных объектов может быть медленным.\\n\\n- Неперечислимые свойства и геттеры/сеттеры: Базовая реализация с `for...in` копирует только enumerable-свойства. Она не копирует дескрипторы свойств (getters/setters) или свойства из цепочки прототипов.\\n\\nВывод:\\nРучная реализация полезна для понимания механизмов языка, но в продакшене лучше использовать встроенные методы (`StructuredClone`) или проверенные библиотеки (например, `lodash.cloneDeep`), которые уже решают все эти сложности.","function deepClone(value, visited = new WeakMap()) {\\n  // 1. Обработка примитивов и null/undefined\\n  if (value === null || typeof value !== \'object\') {\\n    return value;\\n  }\\n\\n  // 2. Обработка циклических ссылок\\n  if (visited.has(value)) {\\n    return visited.get(value);\\n  }\\n\\n  // 3. Обработка специальных встроенных объектов\\n  if (value instanceof Date) {\\n    return new Date(value);\\n  }\\n  if (value instanceof Map) {\\n    const copy = new Map();\\n    visited.set(value, copy);\\n    value.forEach((val, key) => {\\n      copy.set(key, deepClone(val, visited));\\n    });\\n    return copy;\\n  }\\n  // Аналогично для Set, RegExp и других...\\n\\n  // 4. Обработка массивов и обычных объектов\\n  const copy = Array.isArray(value) ? [] : {};\\n  visited.set(value, copy); // Сохраняем копию для проверки циклических ссылок\\n\\n  // Рекурсивное копирование всех свойств\\n  for (let key in value) {\\n    if (value.hasOwnProperty(key)) {\\n      copy[key] = deepClone(value[key], visited);\\n    }\\n  }\\n\\n  return copy;\\n}"],[1137,"Event-loop — это механизм, который обрабатывает асинхронные операции в Node.js. SetImmediate выполняется после операций ввода-вывода и таймеров, но до следующей итерации цикла событий. Он позволяет отложить выполнение кода до завершения текущего цикла.","Event-loop — это ядро асинхронной обработки в Node.js. Он управляет выполнением кода, обрабатывая события и колбэки в определенном порядке.\\nФазы Event-loop:\\n\\n- Timers: Выполняются колбэки от `setTimeout` и `setInterval`\\n\\n- Pending callbacks: Выполняются отложенные системные операции (например, ошибки сети)\\n\\n- Poll: Обрабатывает новые события I/O\\n\\n- Check: Выполняются колбэки `setImmediate`\\n\\n- Close callbacks: Выполняются колбэки закрытия (например, `socket.on(\'close\')`)\\n\\nКогда выполняется setImmediate:\\n\\n- После фазы Poll и перед фазой Close callbacks\\n\\n- В текущей итерации цикла событий, но после операций I/O\\n\\n- Позволяет выполнить код сразу после завершения текущих операций\\n\\nВывод:","console.log(\'Start\');\\n\\nsetImmediate(() => {\\n  console.log(\'setImmediate callback\');\\n});\\n\\nsetTimeout(() => {\\n  console.log(\'setTimeout callback\');\\n}, 0);\\n\\nconsole.log(\'End\');\\n\\nStart\\nEnd\\nsetTimeout callback\\nsetImmediate callback"],[1138,"Блокирующие операции останавливают выполнение кода до завершения операции, что может заморозить приложение. Неблокирующие операции используют колбэки или промисы и позволяют приложению продолжать работу во время ожидания результата.","Блокирующие операции — это синхронные операции, которые останавливают выполнение основного потока до своего завершения.\\nПримеры блокирующих операций:\\n\\n- `fs.readFileSync()` — синхронное чтение файла\\n\\n- `crypto.pbkdf2Sync()` — синхронное хеширование\\n\\n- Длительные вычисления в основном потоке\\n\\nНеблокирующие операции — это асинхронные операции, которые используют колбэки, промисы или async/await.\\nПреимущества неблокирующих операций:\\n\\n- Не блокируют event loop\\n\\n- Позволяют обрабатывать другие запросы\\n\\n- Улучшают масштабируемость приложения\\n\\nКогда использовать:\\n\\n- Блокирующие: для простых скриптов или инициализации\\n\\n- Неблокирующие: для веб-серверов и высоконагруженных приложений","// Блокирующая операция\\nconst data = fs.readFileSync(\'file.txt\');\\nconsole.log(data);\\n\\n// Неблокирующая операция\\nfs.readFile(\'file.txt\', (err, data) => {\\n  if (err) throw err;\\n  console.log(data);\\n});"],[1139,"Микросервисы предлагают независимое развертывание, масштабируемость и технологическое разнообразие, но увеличивают сложность координации, требуют мощной инфраструктуры и могут создавать проблемы с консистентностью данных.","Архитектура микросервисов предполагает разбиение приложения на небольшие, независимые сервисы, каждый из которых отвечает за определенную бизнес-возможность.\\nПлюсы микросервисов:\\n\\n- Независимое развертывание — каждый сервис можно обновлять отдельно\\n\\n- Масштабируемость — можно масштабировать только нужные сервисы\\n\\n- Технологическое разнообразие — разные сервисы можно писать на разных языках/технологиях\\n\\n- Устойчивость к отказам — падение одного сервиса не всегда приводит к падению всей системы\\n\\n- Разделение ответственности — разные команды могут работать над разными сервисами\\n\\nМинусы микросервисов:\\n\\n- Сложность координации — необходимо управлять множеством сервисов\\n\\n- Сложность отладки — трассировка запросов через несколько сервисов\\n\\n- Накладные расходы — требуется инфраструктура для orchestration, мониторинга\\n\\n- Сложность с данными — distributed transactions и eventual consistency\\n\\n- Сетевые задержки — коммуникация между сервисами по сети\\n\\nКогда использовать:\\n\\n- Для больших и сложных приложений\\n\\n- Когда нужна гибкость и частое обновление компонентов\\n\\n- При наличии нескольких команд разработки",null],[1140,"Для коммуникации микросервисов используются синхронные (REST, gRPC) и асинхронные (Kafka, RabbitMQ, NATS) транспорты. Синхронные требуют immediate response, асинхронные используют message brokers для декаплингования сервисов.","Коммуникация между микросервисами — критический аспект распределенных систем. Существует два основных подхода:\\nСинхронная коммуникация:\\n\\n- Клиент ожидает immediate response от сервиса\\n\\n- REST/HTTP — простой, человекочитаемый, на основе HTTP\\n\\n- gRPC — высокопроизводительный, бинарный, на основе HTTP/2\\n\\n- Подходит для request-response сценариев\\n\\nАсинхронная коммуникация:\\n\\n- Сервисы обмениваются сообщениями через брокер\\n\\n- Kafka — высокопроизводительный, persistence, replayability\\n\\n- RabbitMQ — AMQP, гибкая маршрутизация, acknowledged delivery\\n\\n- NATS — легковесный, high-throughput, persistence optional\\n\\n- Подходит для event-driven архитектур\\n\\nПримеры использования:\\n\\nВыбор транспорта зависит от:\\n\\n- Требований к производительности\\n\\n- Необходимости гарантированной доставки\\n\\n- Сложности реализации\\n\\n- Требований к масштабируемости","// Синхронный REST вызов\\naxios.get(\'http://user-service/users/123\')\\n\\n// Асинхронная отправка сообщения\\nkafkaProducer.send({\\n    topic: \'order-created\',\\n    messages: [{ value: JSON.stringify(order) }]\\n})"],[1141,"Основные виды тестов: unit (проверка отдельных компонентов), integration (проверка взаимодействия компонентов), e2e (проверка всей системы). Они различаются scope, скоростью выполнения и сложностью setup.","Тестирование — критическая часть разработки ПО, обеспечивающая качество и надежность кода.\\nОсновные виды тестов:\\n\\n- Unit тесты:\\n\\n- Проверяют отдельные функции/модули\\n\\n- Быстрые, изолированные\\n\\n- Пример: тест функции calculatePrice()\\n\\n- Integration тесты:\\n\\n- Проверяют взаимодействие компонентов\\n\\n- Тестируют API, базы данных, внешние сервисы\\n\\n- Пример: тест создания пользователя через API\\n\\n- End-to-end (E2E) тесты:\\n\\n- Проверяют всю систему от начала до конца\\n\\n- Имитируют поведение пользователя\\n\\n- Медленные, сложные в поддержке\\n\\n- Пример: тест процесса оформления заказа\\n\\n- Нагрузочные тесты:\\n\\n- Проверяют производительность под нагрузкой\\n\\n- Измеряют response time, throughput\\n\\nПирамида тестирования:\\n\\nРекомендации:\\n\\n- Много unit тестов (быстрые, надежные)\\n\\n- Умеренное количество integration тестов\\n\\n- Несколько E2E тестов для критических путей","E2E tests\\n    /      \\"\\"\\nIntegration tests\\n    \\"\\"      /\\n   Unit tests (основание)"],[1142,"Опциональная цепочка (`?.`) — это оператор в JavaScript, который позволяет безопасно обращаться к свойствам вложенных объектов без проверки существования каждого уровня. Если какое-либо свойство в цепочке равно `null` или `undefined`, выражение возвращает `undefined` вместо ошибки. Это упрощает код и делает его более читаемым.","Опциональная цепочка (optional chaining) — это синтаксис, который помогает избежать ошибок при обращении к свойствам объектов, которые могут быть `null` или `undefined`.\\nКак работает:\\n\\n- Используется оператор `?.`\\n\\n- Если свойство перед `?.` равно `null` или `undefined`, выражение возвращает `undefined`\\n\\n- Если свойство существует, обращение происходит как обычно\\n\\nПримеры использования:\\n\\nПрименение:\\n\\n- Для безопасного доступа к свойствам API-ответов\\n\\n- При работе с конфигурационными объектами\\n\\n- Для упрощения кода с множественными проверками","const user = {\\n  profile: {\\n    name: \\"Alice\\",\\n    address: {\\n      city: \\"Moscow\\"\\n    }\\n  }\\n};\\n\\n// Без опциональной цепочки (громоздко)\\nconst city = user && user.profile && user.profile.address && user.profile.address.city;\\n\\n// С опциональной цепочкой (просто)\\nconst citySafe = user?.profile?.address?.city;\\nconsole.log(citySafe); // \\"Moscow\\"\\n\\n// Если свойства нет\\nconst zipCode = user?.profile?.address?.zipCode;\\nconsole.log(zipCode); // undefined"],[1143,"`Pick`, `Omit` и `Partial` — это утилитарные типы TypeScript для работы с объектными типами. `Pick` создает тип из выбранных свойств исходного типа. `Omit` создает тип, исключая указанные свойства. `Partial` делает все свойства типа необязательными.","TypeScript предоставляет несколько полезных утилитарных типов для манипуляции с объектными типами.\\nPick:\\nСоздает новый тип, выбирая только указанные свойства из исходного типа.\\n\\nOmit:\\nСоздает новый тип, исключая указанные свойства.\\n\\nPartial:\\nДелает все свойства типа необязательными.\\n\\nПрактическое применение:\\n\\n- `Pick` для создания типов представлений (DTO)\\n\\n- `Omit` для исключения чувствительных данных\\n\\n- `Partial` для типов обновления (patch operations)","interface User {\\n  id: number;\\n  name: string;\\n  email: string;\\n  age: number;\\n}\\n\\ntype UserPreview = Pick<User, \'id\' | \'name\'>;\\n// Эквивалентно: { id: number; name: string; }\\n\\ntype UserWithoutEmail = Omit<User, \'email\'>;\\n// Эквивалентно: { id: number; name: string; age: number; }\\n\\ntype PartialUser = Partial<User>;\\n// Эквивалентно: { id?: number; name?: string; email?: string; age?: number; }"],[1144,"В Node.js для работы с файлами используется модуль `fs`. Он предоставляет синхронные и асинхронные методы. Асинхронные методы предпочтительнее, так как не блокируют event loop. Для современных приложений рекомендуется использовать Promise-based API (`fs.promises`).","Node.js предоставляет мощный модуль `fs` (File System) для работы с файлами.\\nОсновные подходы:\\n\\n- Синхронные методы (блокирующие):\\n\\n- Асинхронные методы с callback:\\n\\n- Promise-based API (рекомендуется):\\n\\nОсновные операции:\\n\\n- Чтение файлов (`readFile`)\\n\\n- Запись файлов (`writeFile`)\\n\\n- Удаление файлов (`unlink`)\\n\\n- Работа с директориями (`mkdir`, `readdir`)\\n\\nЛучшие практики:\\n\\n- Используйте асинхронные методы для избежания блокировки\\n\\n- Обрабатывайте ошибки с помощью try-catch для promise-based API\\n\\n- Используйте потоки для работы с большими файлами","const fs = require(\'fs\');\\nconst data = fs.readFileSync(\'file.txt\', \'utf8\');\\n\\nfs.readFile(\'file.txt\', \'utf8\', (err, data) => {\\n  if (err) throw err;\\n  console.log(data);\\n});\\n\\nconst fs = require(\'fs\').promises;\\n\\nasync function readFile() {\\n  try {\\n    const data = await fs.readFile(\'file.txt\', \'utf8\');\\n    console.log(data);\\n  } catch (error) {\\n    console.error(error);\\n  }\\n}"],[1145,"CORS (Cross-Origin Resource Sharing) — это механизм безопасности браузеров, который разрешает или запрещает запросы к ресурсам на другом домене. Он предотвращает межсайтовые запросы, которые могут быть опасными. Сервер должен отправлять специальные заголовки, чтобы разрешить кросс-доменные запросы.","CORS — это важный механизм веб-безопасности, который контролирует доступ к ресурсам между разными доменами.\\nКак работает CORS:\\n\\n- Браузер отправляет предварительный запрос (preflight) OPTIONS для проверки разрешений\\n\\n- Сервер отвечает с заголовками, указывающими разрешенные origins, методы и headers\\n\\n- Если запрос разрешен, браузер отправляет основной запрос\\n\\nОсновные заголовки CORS:\\n\\n- `Access-Control-Allow-Origin`: разрешенные домены\\n\\n- `Access-Control-Allow-Methods`: разрешенные HTTP-методы\\n\\n- `Access-Control-Allow-Headers`: разрешенные заголовки\\n\\nПример настройки в Express.js:\\n\\nКогда возникает ошибка CORS:\\n\\n- При запросах между разными доменами\\n\\n- При использовании нестандартных заголовков\\n\\n- При запросах с credentials (куки, авторизация)","const express = require(\'express\');\\nconst cors = require(\'cors\');\\n\\nconst app = express();\\n\\n// Простая настройка\\napp.use(cors());\\n\\n// Кастомная настройка\\napp.use(cors({\\n  origin: \'https://example.com\',\\n  methods: [\'GET\', \'POST\'],\\n  allowedHeaders: [\'Content-Type\']\\n}));"],[1146,"JWT (JSON Web Token) — это стандарт для безопасной передачи информации между сторонами в виде JSON-объекта. Токен состоит из трех частей: заголовка (header), полезной нагрузки (payload) и подписи (signature). Эти части разделяются точками и кодируются в Base64.","JWT — популярный стандарт для аутентификации и авторизации в веб-приложениях.\\nСтруктура JWT:\\nТокен имеет формат: `header.payload.signature`\\n\\n- Header:\\n\\n- Содержит информацию о типе токена и алгоритме подписи\\n\\n- Пример: `{\\"alg\\": \\"HS256\\", yp\\": \\"JWT\\"}`\\n\\n- Payload:\\n\\n- Содержит claims (утверждения) — информацию о пользователе и дополнительные данные\\n\\n- Пример: `{\\"sub\\": \\"123\\",\\name\\": \\"John\\", \\"exp\\": 1516239022}`\\n\\n- Signature:\\n\\n- Создается путем подписи закодированных header и payload с использованием секретного ключа\\n\\n- Гарантирует целостность токена\\n\\nПример создания JWT в Node.js:\\n\\nПреимущества JWT:\\n\\n- Статусность (не требует хранения на сервере)\\n\\n- Поддержка разных алгоритмов подписи\\n\\n- Легкая проверка подлинности\\n\\nБезопасность:\\n\\n- Всегда используйте HTTPS\\n\\n- Храните секретные ключи безопасно\\n\\n- Устанавливайте разумное время expiration","const jwt = require(\'jsonwebtoken\');\\n\\nconst token = jwt.sign(\\n  { userId: 123, role: \'admin\' },\\n  \'secret-key\',\\n  { expiresIn: \'1h\' }\\n);\\nconsole.log(token); // header.payload.signature"],[1147,"Колбэки MutationObserver являются микротасками (microtasks). Они выполняются в той же фазе event loop, что и Promise, но после них. Это обеспечивает высокий приоритет выполнения и гарантирует, что наблюдения за изменениями DOM обрабатываются до следующего рендеринга браузера.","MutationObserver использует микротаски для обеспечения своевременного и эффективного отслеживания изменений DOM.\\nМесто в event loop:\\nПорядок выполнения задач:\\n\\n- Макротаски (Macrotasks): setTimeout, setInterval, I/O\\n\\n- Микротаски (Microtasks): Promise, queueMicrotask, MutationObserver\\n\\n- Рендеринг: Browser repaint/reflow\\n\\n- Следующая итерация: Переход к следующей макротаске\\n\\nДетали реализации:\\nПоведение MutationObserver:\\n\\nПреимущества микротаск:\\nСвоевременность выполнения:\\n\\n- Обработка изменений DOM до следующего рендеринга\\n\\n- Гарантированный порядок относительно других микротаск\\n\\n- Высокий приоритет в event loop\\n\\nЭффективность:\\n\\n- Группировка множественных изменений в один колбэк\\n\\n- Избежание \\"дребезга\\" при частых изменениях\\n\\n- Оптимизация производительности\\n\\nСравнение с другими подходами:\\nMutationObserver vs setTimeout:\\n\\nПрактическое значение:\\n\\n- MutationObserver идеален для реактивных систем\\n\\n- Гарантирует актуальность данных до визуального обновления\\n\\n- Используется в современных фреймворках для отслеживания изменений","// Создание observer\\nconst observer = new MutationObserver((mutations) => {\\n  console.log(\'DOM изменился\'); // Это микротаска\\n});\\n\\n// Наблюдение за изменениями\\nobserver.observe(document.body, {\\n  childList: true,\\n  subtree: true\\n});\\n\\n// Пример порядка выполнения\\nconsole.log(\'Start\');\\n\\nsetTimeout(() => {\\n  console.log(\'setTimeout\'); // Макротаска\\n}, 0);\\n\\nPromise.resolve().then(() => {\\n  console.log(\'Promise\'); // Микротаска\\n});\\n\\n// Изменение DOM\\ndocument.body.appendChild(document.createElement(\'div\'));\\n\\nconsole.log(\'End\');\\n\\n// Порядок вывода:\\n// \\"Start\\"\\n// \\"End\\" \\n// \\"Promise\\" - микротаска Promise\\n// \\"DOM изменился\\" - микротаска MutationObserver\\n// \\"setTimeout\\" - макротаска\\n\\n// MutationObserver (микротаска)\\nobserver.observe(element, { attributes: true });\\nelement.setAttribute(\'data-test\', \'value\');\\n// Колбэк выполнится до следующего рендеринга\\n\\n// setTimeout (макротаска)\\nelement.setAttribute(\'data-test\', \'value\');\\nsetTimeout(() => {\\n  // Колбэк выполнится после рендеринга\\n}, 0);"],[1148,"Для кэширования данных используйте LocalStorage для небольших текстовых данных (до 5MB), IndexedDB для больших объемов и сложных структур. Если IndexedDB не поддерживается, можно использовать LocalStorage как fallback, либо реализовать полифилл для IndexedDB. Для совсем старых браузеров можно использовать cookies или серверное хранение.","Выбор технологии хранения зависит от объема данных, структуры и требований к производительности.\\nСравнение технологий хранения:\\nLocalStorage:\\n\\n- Объем: ~5MB\\n\\n- Тип данных: Только строки\\n\\n- Доступ: Синхронный\\n\\n- Использование:\\n\\nIndexedDB:\\n\\n- Объем: ~50% от свободного места\\n\\n- Тип данных: Любые JS объекты\\n\\n- Доступ: Асинхронный\\n\\n- Использование:\\n\\nСтратегия fallback:\\nОпределение поддержки:\\n\\nУниверсальный адаптер:\\n\\nПолифиллы:\\n\\n- Использование библиотек like `localForage`\\n\\n- Кастомная реализация на LocalStorage для небольших данных\\n\\n- Серверное кэширование как крайний вариант","// Простые данные\\nlocalStorage.setItem(\'user\', JSON.stringify(userData));\\nconst user = JSON.parse(localStorage.getItem(\'user\'));\\n\\nconst request = indexedDB.open(\'MyDatabase\', 1);\\nrequest.onsuccess = (event) => {\\n  const db = event.target.result;\\n  const transaction = db.transaction([\'store\'], \'readwrite\');\\n  const store = transaction.objectStore(\'store\');\\n  store.put(data, \'key\');\\n};\\n\\nconst isIndexedDBSupported = () => {\\n  return \'indexedDB\' in window;\\n};\\n\\nconst isLocalStorageSupported = () => {\\n  try {\\n    localStorage.setItem(\'test\', \'test\');\\n    localStorage.removeItem(\'test\');\\n    return true;\\n  } catch (e) {\\n    return false;\\n  }\\n};\\n\\nclass StorageAdapter {\\n  constructor() {\\n    this.supported = this.detectSupport();\\n  }\\n\\n  detectSupport() {\\n    if (isIndexedDBSupported()) return \'indexeddb\';\\n    if (isLocalStorageSupported()) return \'localstorage\';\\n    return \'none\';\\n  }\\n\\n  async set(key, value) {\\n    switch (this.supported) {\\n      case \'indexeddb\':\\n        return await this.setIndexedDB(key, value);\\n      case \'localstorage\':\\n        return this.setLocalStorage(key, value);\\n      default:\\n        throw new Error(\'No storage support\');\\n    }\\n  }\\n\\n  setLocalStorage(key, value) {\\n    localStorage.setItem(key, JSON.stringify(value));\\n  }\\n\\n  async setIndexedDB(key, value) {\\n    // Реализация IndexedDB\\n  }\\n}"],[1149,"Hoisting (всплытие) - это механизм в JavaScript, при котором объявления переменных и функций \\"поднимаются\\" в начало своей области видимости. Объявления функций поднимаются полностью, а переменные, объявленные через `var` - только объявление, но не инициализация. `let` и `const` также всплывают, но не инициализируются до фактического объявления.","Hoisting влияет на доступность переменных и функций до их фактического объявления в коде.\\nПоведение для разных типов:\\nОбъявления функций:\\n\\nПеременные var:\\n\\nlet и const:\\n\\nПорядок hoisting:\\n\\n- Объявления функций\\n\\n- Объявления переменных\\n\\n- Присваивания значений\\n\\nПример с конфликтами:\\n\\nПрактические последствия:\\n\\n- Всегда объявляйте переменные в начале области видимости\\n\\n- Используйте `let` и `const` вместо `var`\\n\\n- Избегайте переопределения функций переменными","// Работает благодаря hoisting\\nconsole.log(sayHello()); // \\"Hello\\"\\nfunction sayHello() {\\n  return \\"Hello\\";\\n}\\n\\nconsole.log(x); // undefined (всплыло объявление)\\nvar x = 5;\\nconsole.log(x); // 5\\n\\n// Эквивалентно:\\nvar x;\\nconsole.log(x); // undefined\\nx = 5;\\nconsole.log(x); // 5\\n\\nconsole.log(y); // ReferenceError\\nlet y = 10;\\n\\n// Временная мертвая зона (TDZ)\\n// от начала блока до объявления\\n\\nvar myFunction = 1;\\nfunction myFunction() {\\n  return 2;\\n}\\n\\nconsole.log(typeof myFunction); // \\number\\"\\n// Функция всплыла первой, но потом перезаписана переменной"],[1150,"Для принудительного обновления страницы используйте `location.reload()`, который перезагружает текущую страницу. Для полной перезагрузки с очисткой кэша используйте `location.reload(true)`. Также можно установить `location.href = location.href` или использовать `location.replace()` для замены текущей страницы.","Существует несколько методов обновления страницы, каждый со своими особенностями.\\nМетоды обновления:\\n1. location.reload():\\n\\n2. Переустановка URL:\\n\\n3. Навигационные методы:\\n\\nРазличия между методами:\\nlocation.reload() vs location.href:\\n\\n- `reload()` всегда делает запрос к серверу\\n\\n- `location.href` может брать страницу из кэша\\n\\n- `reload(true)` гарантирует свежую версию\\n\\nПример с обработкой:\\n\\nОсобые случаи:\\nОбновление с параметрами:\\n\\nSPA (Single Page Application):\\n\\nРекомендации:\\n\\n- Используйте `location.reload()` для большинства случаев\\n\\n- Добавляйте подтверждение для пользователя\\n\\n- В SPA предпочитайте обновление данных без перезагрузки","// Простое обновление\\nlocation.reload();\\n\\n// Принудительное обновление с очисткой кэша\\nlocation.reload(true);\\n\\n// Эффект похож на reload()\\nlocation.href = location.href;\\n\\n// Без добавления в историю браузера\\nlocation.replace(location.href);\\n\\n// Использование history API\\nhistory.go(0);\\n\\n// Аналогично reload()\\nhistory.go();\\n\\nfunction forceReload() {\\n  try {\\n    // Пытаемся принудительно обновить\\n    location.reload(true);\\n  } catch (e) {\\n    // Fallback для старых браузеров\\n    location.href = location.href + \'?force=\' + Date.now();\\n  }\\n}\\n\\n// Обновление с подтверждением\\nfunction confirmReload() {\\n  if (confirm(\'Обновить страницу?\')) {\\n    location.reload();\\n  }\\n}\\n\\n// Добавление timestamp для избежания кэширования\\nlocation.search = \'?refresh=\' + Date.now();\\n\\n// В SPA вместо полного обновления\\nwindow.dispatchEvent(new Event(\'forceRefresh\'));\\n// Компоненты обрабатывают событие и обновляют данные"],[1151,"Полностью всплывают только Function Declarations (объявления функций). Function Expressions (функциональные выражения), включая стрелочные функции, не всплывают - всплывает только объявление переменной, но не присваивание функции. Объявления классов также не всплывают.","Поведение hoisting значительно различается в зависимости от способа объявления функции.\\nFunction Declaration (полное всплытие):\\n\\nFunction Expression (частичное всплытие):\\n\\nСтрелочные функции:\\n\\nКлассы:\\n\\nПрактический пример:\\n\\nРекомендации:\\n\\n- Используйте Function Declarations для утилитных функций\\n\\n- Для callbacks и методов используйте Function Expressions\\n\\n- Всегда объявляйте функции до их использования","// Работает - функция полностью доступна\\nsayHello(); // \\"Hello\\"\\n\\nfunction sayHello() {\\n  return \\"Hello\\";\\n}\\n\\n// Не работает - переменная всплыла, но равна undefined\\nsayHello(); // TypeError: sayHello is not a function\\n\\nvar sayHello = function() {\\n  return \\"Hello\\";\\n};\\n\\n// Не работает - аналогично Function Expression\\nsayHello(); // ReferenceError (let/const) или TypeError (var)\\n\\nconst sayHello = () => {\\n  return \\"Hello\\";\\n};\\n\\n// Не работает - классы не всплывают\\nconst obj = new MyClass(); // ReferenceError\\n\\nclass MyClass {\\n  constructor() {}\\n}\\n\\n// Function Declaration - работает\\nconsole.log(add(2, 3)); // 5\\nfunction add(a, b) { return a + b; }\\n\\n// Function Expression - не работает\\nconsole.log(multiply(2, 3)); // TypeError\\nvar multiply = function(a, b) { return a * b; };\\n\\n// Стрелочная функция - не работает  \\nconsole.log(divide(6, 2)); // ReferenceError\\nconst divide = (a, b) => a / b;"],[1152,"Для глубокого копирования объектов используйте `JSON.parse(JSON.stringify(obj))` для простых объектов, `structuredClone()` для современных браузеров, или библиотеки типа Lodash `_.cloneDeep()`. Ручная рекурсивная функция также подходит для сложных случаев. Каждый метод имеет свои ограничения и особенности.","Глубокое копирование создает полностью независимую копию объекта со всеми вложенными свойствами.\\nМетоды копирования:\\n1. JSON метод (простой, но с ограничениями):\\n\\n2. structuredClone (современный стандарт):\\n\\n3. Рекурсивная функция:\\n\\n4. Lodash cloneDeep:\\n\\nПример с циклическими ссылками:\\n\\nРекомендации:\\n\\n- Используйте `structuredClone` для современных приложений\\n\\n- Для legacy поддержки - Lodash или JSON метод\\n\\n- Для особых случаев - кастомную рекурсивную функцию","const obj = { a: 1, b: { c: 2 } };\\nconst copy = JSON.parse(JSON.stringify(obj));\\n\\n// Ограничения:\\n// - Игнорирует функции, undefined, Symbol\\n// - Преобразует Date в строки\\n// - Теряет прототипы и конструкторы\\n\\n// Нативный метод для глубокого копирования\\nconst obj = { a: 1, b: { c: 2 } };\\nconst copy = structuredClone(obj);\\n\\n// Поддерживает:\\n// - Map, Set, Date, RegExp, ArrayBuffer\\n// - Циклические ссылки\\n\\nfunction deepClone(obj, hash = new WeakMap()) {\\n  if (obj === null || typeof obj !== \'object\') return obj;\\n  if (hash.has(obj)) return hash.get(obj);\\n  if (obj instanceof Date) return new Date(obj);\\n  if (obj instanceof RegExp) return new RegExp(obj);\\n\\n  const clone = Array.isArray(obj) ? [] : {};\\n  hash.set(obj, clone);\\n\\n  for (let key in obj) {\\n    if (obj.hasOwnProperty(key)) {\\n      clone[key] = deepClone(obj[key], hash);\\n    }\\n  }\\n\\n  return clone;\\n}\\n\\nconst _ = require(\'lodash\');\\nconst copy = _.cloneDeep(original);\\n\\nconst obj = { a: 1 };\\nobj.self = obj;\\n\\n// JSON метод упадет\\n// JSON.parse(JSON.stringify(obj)); // TypeError\\n\\n// structuredClone работает\\nconst copy = structuredClone(obj); // Успешно"],[1153,"Spread оператор \\"разворачивает\\" элементы массивов или свойства объектов, а rest параметры \\"собирают\\" оставшиеся аргументы в массив или оставшиеся свойства в объект. Spread используется в правой части выражения, rest - в левой, в контексте деструктуризации или параметров функции.","Один и тот же оператор `...` используется для двух противоположных операций в зависимости от контекста.\\nSpread оператор (разворот):\\nДля массивов:\\n\\nДля объектов:\\n\\nRest параметры (сбор):\\nВ параметрах функции:\\n\\nВ деструктуризации массивов:\\n\\nВ деструктуризации объектов:\\n\\nПрактические примеры:\\nКомбинирование:\\n\\nКлонирование с исключением:","const arr1 = [1, 2, 3];\\nconst arr2 = [4, 5, 6];\\nconst combined = [...arr1, ...arr2]; // [1, 2, 3, 4, 5, 6]\\n\\n// Копирование массива\\nconst copy = [...arr1]; // [1, 2, 3]\\n\\nconst obj1 = { a: 1, b: 2 };\\nconst obj2 = { c: 3, d: 4 };\\nconst merged = { ...obj1, ...obj2 }; // { a: 1, b: 2, c: 3, d: 4 }\\n\\n// Переопределение свойств\\nconst updated = { ...obj1, b: 20 }; // { a: 1, b: 20 }\\n\\nfunction sum(...numbers) {\\n  return numbers.reduce((total, num) => total + num, 0);\\n}\\nsum(1, 2, 3, 4); // 10\\n\\nconst [first, second, ...rest] = [1, 2, 3, 4, 5];\\n// first = 1, second = 2, rest = [3, 4, 5]\\n\\nconst { a, b, ...other } = { a: 1, b: 2, c: 3, d: 4 };\\n// a = 1, b = 2, other = { c: 3, d: 4 }\\n\\nfunction process(first, second, ...others) {\\n  console.log(first, second); // 1, 2\\n  console.log(others); // [3, 4, 5]\\n}\\n\\nconst numbers = [1, 2, 3, 4, 5];\\nprocess(...numbers); // Spread для передачи, rest для сбора\\n\\nconst original = { a: 1, b: 2, c: 3, d: 4 };\\nconst { b, ...withoutB } = original;\\n// withoutB = { a: 1, c: 3, d: 4 }"],[1154,"Промисы пришли на смену callback hell и предоставили более чистый способ работы с асинхронными операциями. Промис имеет три состояния: pending (ожидание), fulfilled (выполнено успешно) и rejected (выполнено с ошибкой). После перехода в fulfilled или rejected состояние промиса больше не меняется.","Промисы решают проблемы асинхронного кода, которые были характерны для callback-based подхода.\\nЭволюция асинхронности:\\nCallback Hell:\\n\\nPromise решение:\\n\\nСостояния Promise:\\n1. Pending (Ожидание):\\n\\n2. Fulfilled (Выполнено):\\n\\n3. Rejected (Отклонено):\\n\\nСхема переходов:\\n\\nОпределение состояния:\\n\\nОсобенности:\\n\\n- Состояние изменяется только один раз\\n\\n- Нельзя отменить выполнение Promise\\n\\n- Цепочка then/catch создает новые Promise\\n\\nПреимущества над callback\'ами:\\n\\n- Читаемый последовательный код\\n\\n- Централизованная обработка ошибок\\n\\n- Возможность комбинирования через Promise.all/race","// Проблема вложенных callback\'ов\\ngetData(function(data1) {\\n  processData(data1, function(data2) {\\n    saveData(data2, function(data3) {\\n      displayData(data3, function() {\\n        // И так далее...\\n      });\\n    });\\n  });\\n});\\n\\ngetData()\\n  .then(processData)\\n  .then(saveData)\\n  .then(displayData)\\n  .catch(handleError);\\n\\nconst promise = new Promise((resolve, reject) => {\\n  // Асинхронная операция еще не завершена\\n});\\n// promise.state = \'pending\'\\n\\nconst promise = Promise.resolve(\'success\');\\n// или\\nconst promise = new Promise((resolve) => {\\n  resolve(\'success\');\\n});\\n// promise.state = \'fulfilled\'\\n\\nconst promise = Promise.reject(new Error(\'failure\'));\\n// или\\nconst promise = new Promise((resolve, reject) => {\\n  reject(new Error(\'failure\'));\\n});\\n// promise.state = \'rejected\'\\n\\nPending\\n   ↓\\nFulfilled (с значением)\\n   или  \\nRejected (с причиной ошибки)\\n\\nconst promise = someAsyncOperation();\\n\\npromise.then(\\n  value => {\\n    console.log(\'Fulfilled:\', value);\\n  },\\n  error => {\\n    console.log(\'Rejected:\', error);\\n  }\\n);"],[1155,"Основные статические методы Promise: `Promise.all()` для ожидания всех промисов, `Promise.race()` для первого завершившегося, `Promise.allSettled()` для всех результатов (успешных и неудачных), `Promise.any()` для первого успешного, `Promise.resolve()` и `Promise.reject()` для создания сразу resolved/rejected промисов.","Статические методы Promise предоставляют мощные инструменты для работы с множеством асинхронных операций.\\nМетоды для коллекций:\\nPromise.all() - все успешно:\\n\\nPromise.race() - первый завершившийся:\\n\\nPromise.allSettled() - все результаты:\\n\\nPromise.any() - первый успешный:\\n\\nМетоды создания:\\nPromise.resolve() - успешный промис:\\n\\nPromise.reject() - промис с ошибкой:","const promises = [\\n  fetch(\'/api/users\'),\\n  fetch(\'/api/products\'),\\n  fetch(\'/api/orders\')\\n];\\n\\nPromise.all(promises)\\n  .then(([users, products, orders]) => {\\n    // Все промисы выполнены успешно\\n  })\\n  .catch(error => {\\n    // Хотя бы один промис отклонен\\n  });\\n\\nconst timeout = new Promise((_, reject) => {\\n  setTimeout(() => reject(new Error(\'Timeout\')), 5000);\\n});\\n\\nPromise.race([fetch(\'/api/data\'), timeout])\\n  .then(data => {\\n    // fetch завершился раньше timeout\\n  })\\n  .catch(error => {\\n    // timeout сработал раньше\\n  });\\n\\nconst promises = [promise1, promise2, promise3];\\n\\nPromise.allSettled(promises)\\n  .then(results => {\\n    results.forEach(result => {\\n      if (result.status === \'fulfilled\') {\\n        console.log(\'Успех:\', result.value);\\n      } else {\\n        console.log(\'Ошибка:\', result.reason);\\n      }\\n    });\\n  });\\n\\nconst mirrors = [\\n  fetch(\'https://mirror1.com/data\'),\\n  fetch(\'https://mirror2.com/data\'),\\n  fetch(\'https://mirror3.com/data\')\\n];\\n\\nPromise.any(mirrors)\\n  .then(data => {\\n    // Первый успешный ответ\\n  })\\n  .catch(errors => {\\n    // Все промисы отклонены\\n  });\\n\\nconst resolved = Promise.resolve(42);\\n// Эквивалентно: new Promise(resolve => resolve(42))\\n\\n// Использование для кэширования\\nconst cache = new Map();\\nfunction getData(key) {\\n  if (cache.has(key)) {\\n    return Promise.resolve(cache.get(key));\\n  }\\n  return fetchData(key);\\n}\\n\\nconst rejected = Promise.reject(new Error(\'Failure\'));\\n// Эквивалентно: new Promise((_, reject) => reject(error))"],[1156,"Для работы с WebSockets можно использовать библиотеку Socket.IO, которая предоставляет дополнительные возможности поверх нативного WebSocket API, такие как автоматические reconnection, room management и fallback polling. Также популярны ws для Node.js сервера, uWebSockets.js для высокой производительности, и нативный WebSocket API для простых случаев.","Различные библиотеки предоставляют разные уровни абстракции для работы с WebSockets.\\nSocket.IO (самая популярная):\\nКлиентская часть:\\n\\nСерверная часть (Node.js):\\n\\nАльтернативные библиотеки:\\nws (легковесная для Node.js):\\n\\nuWebSockets.js (высокая производительность):\\n\\nНативный WebSocket API:\\n\\nДополнительные возможности Socket.IO:\\nКомнаты (Rooms):","import io from \'socket.io-client\';\\n\\nconst socket = io(\'http://localhost:3000\', {\\n  transports: [\'websocket\', \'polling\'] // Fallback\\n});\\n\\n// События подключения\\nsocket.on(\'connect\', () => {\\n  console.log(\'Connected to server\');\\n});\\n\\n// Отправка данных\\nsocket.emit(\'chat message\', \'Hello world\');\\n\\n// Получение данных\\nsocket.on(\'chat message\', (msg) => {\\n  console.log(\'Message received:\', msg);\\n});\\n\\n// Автоматическое переподключение\\nsocket.on(\'reconnect\', (attempt) => {\\n  console.log(`Reconnected after ${attempt} attempts`);\\n});\\n\\nconst express = require(\'express\');\\nconst http = require(\'http\');\\nconst { Server } = require(\'socket.io\');\\n\\nconst app = express();\\nconst server = http.createServer(app);\\nconst io = new Server(server);\\n\\nio.on(\'connection\', (socket) => {\\n  console.log(\'User connected:\', socket.id);\\n\\n  socket.on(\'chat message\', (msg) => {\\n    // Broadcast всем клиентам\\n    io.emit(\'chat message\', msg);\\n  });\\n\\n  socket.on(\'disconnect\', () => {\\n    console.log(\'User disconnected\');\\n  });\\n});\\n\\nserver.listen(3000);\\n\\nconst WebSocket = require(\'ws\');\\nconst wss = new WebSocket.Server({ port: 8080 });\\n\\nwss.on(\'connection\', (ws) => {\\n  ws.on(\'message\', (message) => {\\n    console.log(\'Received:\', message);\\n  });\\n\\n  ws.send(\'Hello from server\');\\n});\\n\\nconst uWS = require(\'uWebSockets.js\');\\n\\nuWS.App().ws(\'/*\', {\\n  open: (ws) => {\\n    console.log(\'Client connected\');\\n  },\\n  message: (ws, message) => {\\n    ws.send(message);\\n  }\\n}).listen(3000);\\n\\nconst socket = new WebSocket(\'ws://localhost:8080\');\\n\\nsocket.onopen = () => {\\n  socket.send(\'Hello Server!\');\\n};\\n\\nsocket.onmessage = (event) => {\\n  console.log(\'Message from server:\', event.data);\\n};\\n\\nsocket.onclose = () => {\\n  console.log(\'Connection closed\');\\n};\\n\\n// Сервер\\nsocket.join(\'room1\');\\nio.to(\'room1\').emit(\'message\', \'Hello room\');\\n\\n// Namespaces\\nconst adminNamespace = io.of(\'/admin\');\\nadminNamespace.on(\'connection\', (socket) => {\\n  // Только для админов\\n});"],[1157,"Если сервер не поддерживает WebSockets, можно использовать Server-Sent Events (SSE) для one-way коммуникации, long polling для эмуляции real-time, short polling для периодических запросов, или WebRTC для peer-to-peer соединений. Также можно использовать коммерческие сервисы like Pusher или Firebase для real-time функциональности.","Существует несколько стратегий для эмуляции real-time поведения без WebSockets.\\n1. Server-Sent Events (SSE):\\nКлиент:\\n\\nСервер (Node.js + Express):\\n\\n2. Long Polling:\\nКлиент:\\n\\nСервер:\\n\\n3. Short Polling:\\nКлиент:\\n\\n4. Comet (Hidden iframe):\\n\\n5. WebRTC Data Channels:\\n\\nFallback стратегия:","const eventSource = new EventSource(\'/updates\');\\n\\neventSource.onmessage = (event) => {\\n  const data = JSON.parse(event.data);\\n  console.log(\'Update received:\', data);\\n};\\n\\neventSource.onerror = (error) => {\\n  console.error(\'SSE error:\', error);\\n};\\n\\n// Закрытие соединения\\n// eventSource.close();\\n\\napp.get(\'/updates\', (req, res) => {\\n  res.writeHead(200, {\\n    \'Content-Type\': \'text/event-stream\',\\n    \'Cache-Control\': \'no-cache\',\\n    \'Connection\': \'keep-alive\',\\n  });\\n\\n  // Отправка данных каждые 5 секунд\\n  const interval = setInterval(() => {\\n    res.write(`data: ${JSON.stringify({ time: Date.now() })}\\"\\n\\"\\n`);\\n  }, 5000);\\n\\n  // Очистка при разрыве соединения\\n  req.on(\'close\', () => {\\n    clearInterval(interval);\\n  });\\n});\\n\\nfunction longPoll() {\\n  fetch(\'/messages\')\\n    .then(response => response.json())\\n    .then(messages => {\\n      // Обработка сообщений\\n      processMessages(messages);\\n      \\n      // Немедленно начинаем следующий запрос\\n      longPoll();\\n    })\\n    .catch(error => {\\n      console.error(\'Polling error:\', error);\\n      // Повтор через 5 секунд при ошибке\\n      setTimeout(longPoll, 5000);\\n    });\\n}\\n\\n// Запуск long polling\\nlongPoll();\\n\\nconst messagesQueue = [];\\n\\napp.get(\'/messages\', (req, res) => {\\n  // Ждем новые сообщения до 30 секунд\\n  const checkMessages = () => {\\n    if (messagesQueue.length > 0) {\\n      res.json(messagesQueue.splice(0));\\n    } else {\\n      setTimeout(checkMessages, 1000);\\n    }\\n  };\\n\\n  // Таймаут 30 секунд\\n  const timeout = setTimeout(() => {\\n    res.json([]);\\n  }, 30000);\\n\\n  checkMessages();\\n});\\n\\n// Добавление сообщения\\napp.post(\'/messages\', (req, res) => {\\n  messagesQueue.push(req.body);\\n  res.json({ status: \'ok\' });\\n});\\n\\n// Периодические запросы каждые 5 секунд\\nsetInterval(() => {\\n  fetch(\'/updates\')\\n    .then(response => response.json())\\n    .then(updates => {\\n      if (updates.length > 0) {\\n        handleUpdates(updates);\\n      }\\n    });\\n}, 5000);\\n\\n// Исторический подход\\nfunction createCometConnection() {\\n  const iframe = document.createElement(\'iframe\');\\n  iframe.style.display = \'none\';\\n  iframe.src = \'/comet-endpoint\';\\n  document.body.appendChild(iframe);\\n  \\n  // Сервер постепенно отправляет данные в iframe\\n}\\n\\n// Peer-to-peer соединение\\nconst peerConnection = new RTCPeerConnection();\\nconst dataChannel = peerConnection.createDataChannel(\'chat\');\\n\\ndataChannel.onmessage = (event) => {\\n  console.log(\'Received:\', event.data);\\n};\\n\\ndataChannel.onopen = () => {\\n  dataChannel.send(\'Hello via WebRTC!\');\\n};\\n\\nfunction createRealtimeConnection(url) {\\n  // Проверяем поддержку WebSockets\\n  if (\'WebSocket\' in window) {\\n    try {\\n      return new WebSocket(url);\\n    } catch (e) {\\n      // WebSocket недоступен, используем fallback\\n    }\\n  }\\n  \\n  // Проверяем поддержку SSE\\n  if (\'EventSource\' in window) {\\n    return new EventSource(url);\\n  }\\n  \\n  // Используем long polling как последний вариант\\n  return createLongPollingConnection(url);\\n}"],[1158,"Для выноса выполнения скрипта в отдельный поток можно использовать Web Workers для параллельного выполнения, Service Workers для фоновых задач, или Worker Threads в Node.js. Также можно использовать `setTimeout` и `setImmediate` для разбивки тяжелых задач на части, или `requestIdleCallback` для выполнения во время простоя браузера.","Различные API позволяют выполнять код вне основного потока для улучшения производительности.\\n1. Web Workers:\\nСоздание worker:\\n\\nworker.js:\\n\\n2. Service Workers:\\nРегистрация:\\n\\n3. Worker Threads в Node.js:\\n\\n4. Разбивка тяжелых задач:\\nИспользование setTimeout:\\n\\nИспользование requestIdleCallback:\\n\\n5. OffscreenCanvas для графики:\\n\\nОграничения Workers:\\n\\n- Нет доступа к DOM\\n\\n- Ограниченный доступ к window API\\n\\n- Данные передаются через сообщения (serialized)\\n\\n- Более сложная отладка","// main.js\\nconst worker = new Worker(\'worker.js\');\\n\\n// Отправка данных в worker\\nworker.postMessage({ type: \'process\', data: largeArray });\\n\\n// Получение результатов\\nworker.onmessage = (event) => {\\n  console.log(\'Result from worker:\', event.data);\\n};\\n\\n// Обработка ошибок\\nworker.onerror = (error) => {\\n  console.error(\'Worker error:\', error);\\n};\\n\\n// Обработка сообщений из основного потока\\nself.onmessage = function(event) {\\n  const { type, data } = event.data;\\n  \\n  if (type === \'process\') {\\n    // Тяжелые вычисления\\n    const result = heavyComputation(data);\\n    \\n    // Отправка результата обратно\\n    self.postMessage(result);\\n  }\\n};\\n\\nfunction heavyComputation(data) {\\n  // Вычисления, которые не блокируют основной поток\\n  return data.map(item => item * 2);\\n}\\n\\n// Регистрация service worker\\nif (\'serviceWorker\' in navigator) {\\n  navigator.serviceWorker.register(\'/sw.js\')\\n    .then(registration => {\\n      console.log(\'Service Worker registered\');\\n    });\\n}\\n\\n// sw.js - кэширование и фоновые задачи\\nself.addEventListener(\'fetch\', (event) => {\\n  event.respondWith(\\n    caches.match(event.request)\\n      .then(response => response || fetch(event.request))\\n  );\\n});\\n\\nconst { Worker } = require(\'worker_threads\');\\n\\nfunction runService(workerData) {\\n  return new Promise((resolve, reject) => {\\n    const worker = new Worker(\'./worker.js\', { workerData });\\n    worker.on(\'message\', resolve);\\n    worker.on(\'error\', reject);\\n    worker.on(\'exit\', (code) => {\\n      if (code !== 0) {\\n        reject(new Error(`Worker stopped with exit code ${code}`));\\n      }\\n    });\\n  });\\n}\\n\\n// worker.js\\nconst { workerData, parentPort } = require(\'worker_threads\');\\nparentPort.postMessage(heavyComputation(workerData));\\n\\nfunction processInChunks(array, chunkSize, callback) {\\n  let index = 0;\\n\\n  function processChunk() {\\n    const chunk = array.slice(index, index + chunkSize);\\n    \\n    // Обработка чанка\\n    chunk.forEach(processItem);\\n    \\n    index += chunkSize;\\n    \\n    if (index < array.length) {\\n      // Продолжаем в следующем frame\\n      setTimeout(processChunk, 0);\\n    } else {\\n      callback();\\n    }\\n  }\\n  \\n  processChunk();\\n}\\n\\nfunction processDuringIdleTime(tasks) {\\n  function processTask(deadline) {\\n    while (tasks.length > 0 && deadline.timeRemaining() > 0) {\\n      const task = tasks.shift();\\n      executeTask(task);\\n    }\\n\\n    if (tasks.length > 0) {\\n      requestIdleCallback(processTask);\\n    }\\n  }\\n\\n  requestIdleCallback(processTask);\\n}\\n\\n// Рендеринг canvas в worker\\nconst offscreen = canvas.transferControlToOffscreen();\\nconst worker = new Worker(\'canvas-worker.js\');\\n\\nworker.postMessage({ canvas: offscreen }, [offscreen]);\\n\\n// canvas-worker.js\\nself.onmessage = function(event) {\\n  const canvas = event.data.canvas;\\n  const ctx = canvas.getContext(\'2d\');\\n  \\n  // Рендеринг без блокировки основного потока\\n  ctx.fillStyle = \'red\';\\n  ctx.fillRect(0, 0, canvas.width, canvas.height);\\n};"],[1159,"Монолит — это единое приложение, где все компоненты развертываются вместе. Микросервисы — это набор небольших независимых сервисов. Монолит проще в разработке и развертывании на старте, но сложнее масштабируется и изменяется. Микросервисы позволяют независимо масштабировать и развивать части системы, но добавляют сложность в оркестрации и мониторинге.","Выбор между монолитом и микросервисами — это компромисс между простотой и гибкостью.\\nМонолитная архитектура:\\n\\n- Плюсы:\\n\\n- Простота разработки: Единая кодовая база, простые коммуникации между компонентами.\\n\\n- Простота развертывания: Развертывается одно приложение.\\n\\n- Простота отладки: Все логи и трассировки в одном месте.\\n\\n- Минусы:\\n\\n- Сложность масштабирования: Можно масштабировать только все приложение целиком.\\n\\n- Технологический долг: Кодовая база со временем становится громоздкой и сложной для понимания.\\n\\n- Надежность: Падение одного компонента может привести к падению всей системы.\\n\\nМикросервисная архитектура:\\n\\n- Плюсы:\\n\\n- Независимое масштабирование: Каждый сервис можно масштабировать отдельно.\\n\\n- Гибкость технологий: Для каждого сервиса можно использовать подходящий стек технологий.\\n\\n- Устойчивость к сбоям: Падение одного сервиса не всегда приводит к остановке всей системы.\\n\\n- Независимые команды: Команды могут работать над разными сервисами независимо.\\n\\n- Минусы:\\n\\n- Высокая сложность: Сложность сетевых взаимодействий, распределенных транзакций, мониторинга и отладки.\\n\\n- Накладные расходы: Требует инфраструктуры для оркестрации (Kubernetes), обнаружения сервисов, логирования.\\n\\n- Сложность развертывания: Необходимо координировать развертывание множества сервисов.\\n\\nКогда что использовать:\\n\\n- Используйте Монолит: для небольших проектов, стартапов, команд с ограниченными ресурсами или когда требования к продукту еще не стабилизировались.\\n\\n- Рассматривайте Микросервисы: для больших, сложных систем с четкими границами доменов, когда требуется независимое масштабирование компонентов и есть команда, готовая к эксплуатационной сложности.\\n\\nВывод: Не стоит начинать с микросервисов \\"на будущее\\". Начинайте с монолита, и когда появятся веские причины (например, узкие места в масштабировании), выделяйте сервисы.",null],[1160,"SOLID — это набор из пяти принципов, которые помогают писать понятный, гибкий и легко поддерживаемый код. Они включают: Single Responsibility (единственная ответственность), Open/Closed (открытость/закрытость), Liskov Substitution (подстановка Лисков), Interface Segregation (разделение интерфейсов) и Dependency Inversion (инверсия зависимостей).","Эти принципы направлены на создание программного обеспечения, которое легко понимать, расширять и модифицировать.\\nРасшифровка принципов SOLID:\\n\\n- S: Принцип единственной ответственности (Single Responsibility Principle)\\n\\n- Определение: Каждый класс или модуль должен иметь одну и только одну причину для изменения, то есть одну ответственность.\\n\\n- Пример: Класс `UserService` должен отвечать только за бизнес-логику пользователей, а не за отправку email или логирование в файл. Эти задачи нужно вынести в отдельные классы (`EmailService`, `Logger`).\\n\\n- O: Принцип открытости/закрытости (Open/Closed Principle)\\n\\n- Определение: Программные сущности должны быть открыты для расширения, но закрыты для модификации.\\n\\n- Пример: Вместо того чтобы изменять существующую функцию для добавления нового типа, лучше использовать полиморфизм. Добавляется новый класс, который реализует общий интерфейс, а основная логика работает с этим интерфейсом.\\n\\n- L: Принцип подстановки Лисков (Liskov Substitution Principle)\\n\\n- Определение: Объекты в программе должны быть заменяемыми на экземпляры их подтипов без изменения правильности программы.\\n\\n- Пример: Если у вас есть функция, принимающая базовый класс `Bird`, она должна корректно работать и с его наследником `Penguin` (который не умеет летать), не ломаясь из-за этого.\\n\\n- I: Принцип разделения интерфейсов (Interface Segregation Principle)\\n\\n- Определение: Много специализированных интерфейсов лучше, чем один универсальный. Клиенты не должны зависеть от методов, которые они не используют.\\n\\n- Пример: Вместо большого интерфейса `IMultiFunctionDevice` с методами `print()`, `scan()`, `fax()`, лучше создать отдельные интерфейсы `IPrinter`, `IScanner`. Тогда старый принтер сможет реализовать только `IPrinter`.\\n\\n- D: Принцип инверсии зависимостей (Dependency Inversion Principle)\\n\\n- Определение:\\n\\n- Модули верхних уровней не должны зависеть от модулей нижних уровней. Оба типа модулей должны зависеть от абстракций.\\n\\n- Абстракции не должны зависеть от деталей. Детали должны зависеть от абстракций.\\n\\n- Пример: Сервис (`UserService`) не должен напрямую создавать экземпляр репозитория для работы с БД (`UserRepository`). Вместо этого он должен зависеть от абстракции (интерфейса `IUserRepository`). Конкретная реализация (например, `PostgresUserRepository`) внедряется извне (через конструктор), часто с помощью DI-контейнера, как в Nest.js.\\n\\nВывод: Следование принципам SOLID приводит к созданию кода с низкой связанностью и высокой связностью, что облегчает его тестирование, рефакторинг и развитие в долгосрочной перспективе.",null],[1161,"`setInterval` выполняет функцию с фиксированной задержкой, не учитывая частоту обновления экрана, что может приводить к пропуску кадров и лишним вычислениям. `requestAnimationFrame` синхронизирует выполнение кода анимации с частотой обновления экрана (обычно 60 кадров/с), что делает анимацию плавной и эффективной. Он также автоматически останавливается, когда пользователь переходит на другую вкладку, экономя ресурсы. Для плавных анимаций всегда следует предпочитать `requestAnimationFrame`.","Анимация — это процесс изменения свойств элемента с течением времени. В JavaScript для этого можно использовать разные таймеры, но они сильно отличаются по своему поведению и эффективности.\\nsetInterval\\n\\n- Принцип работы: Запускает функцию повторно через заданный фиксированный интервал времени (в миллисекундах).\\n\\n- Проблемы:\\n\\n- Несинхронизирован с отрисовкой: Он не знает, когда браузер готов перерисовать страницу. Это может привести к \\"конфликту\\" — функция пытается изменить стиль, пока браузер занят отрисовкой, из-за чего кадр пропускается, и анимация дергается.\\n\\n- Работа в фоне: Таймер продолжает тикать, даже когда вкладка неактивна, напрасно расходуя заряд батареи и вычислительные ресурсы.\\n\\nrequestAnimationFrame (rAF)\\n\\n- Принцип работы: Сообщает браузеру, что вы хотите выполнить анимацию. Браузер сам оптимизирует вызов вашей функции, выполняя ее непосредственно перед следующей отрисовкой страницы.\\n\\n- Преимущества:\\n\\n- Синхронизация: Гарантирует, что ваш код анимации выполняется в идеальный момент для обновления кадра, обеспечивая максимальную плавность.\\n\\n- Эффективность: Браузер объединяет все `requestAnimationFrame`-вызовы в одном кадре, а также приостанавливает анимацию на неактивных вкладках.\\n\\n- Точность: Передает в функцию-колбэк метку времени (timestamp), что позволяет точно рассчитывать анимацию, даже если частота кадров плавает.\\n\\nВывод: Для создания плавных, производительных и ресурсоэффективных анимаций всегда используйте `requestAnimationFrame`. `setInterval` и `setTimeout` подходят для задач, не требующих точной синхронизации с отрисовкой (например, периодическая проверка состояния).","// Пример с setInterval (НЕ РЕКОМЕНДУЕТСЯ для анимаций)\\nconst intervalId = setInterval(() => {\\n  moveElementByOnePixel(); // Двигаем элемент\\n  if (animationIsComplete) clearInterval(intervalId);\\n}, 16); // ~60fps (1000ms / 60 ≈ 16ms)\\n\\n// Пример с requestAnimationFrame (РЕКОМЕНДУЕМЫЙ способ)\\nfunction animate(timestamp) {\\n  // Высчитываем, насколько сдвинуть элемент на основе timestamp\\n  moveElementBasedOnTime(timestamp);\\n\\n  if (animationIsComplete) return; // Останавливаем анимацию\\n\\n  requestAnimationFrame(animate); // Запрашиваем следующий кадр\\n}\\n\\nrequestAnimationFrame(animate); // Запускаем анимацию"],[1162,"Чистая функция (Pure function) — это функция, которая при одинаковых входных аргументах всегда возвращает одинаковый результат и не имеет побочных эффектов (не изменяет внешнее состояние или переданные ей аргументы). Ее работа зависит только от своих входных данных, что делает ее поведение предсказуемым и легко тестируемым.","Чистые функции — это краеугольный камень функционального программирования и написания надежного кода.\\nХарактеристики чистой функции:\\n\\n- Детерминированность: Для одних и тех же аргументов всегда возвращает один и тот же результат. Не зависит от скрытого состояния или изменяющихся внешних данных (например, глобальных переменных, текущего времени).\\n\\n- Отсутствие побочных эффектов (Side Effects): Не производит наблюдаемых изменений вне функции. Это означает, что она:\\n\\n- Не изменяет свои входные аргументы.\\n\\n- Не модифицирует глобальные переменные.\\n\\n- Не выполняет операций ввода-вывода (например, запросы к сети, чтение файлов).\\n\\n- Не вызывает `Math.random()` или `Date.now()` (так как их результат непредсказуем).\\n\\nПримеры:\\n\\nПреимущества чистых функций:\\n\\n- Предсказуемость: Легко понять, что делает функция.\\n\\n- Тестируемость: Не требуется сложная настройка окружения. Достаточно передать аргументы и проверить результат.\\n\\n- Переиспользование: Их можно безопасно использовать в разных частях приложения.\\n\\n- Кеширование: Результат можно закешировать (мемоизировать) на основе аргументов, чтобы избежать повторных вычислений.\\n\\nВывод\\nСтремитесь к написанию чистых функций везде, где это возможно, так как они делают код более стабильным и понятным. Нечистые функции (например, для взаимодействия с DOM, сетью или глобальным состоянием) следует изолировать и явно идентифицировать.","// ЧИСТАЯ ФУНКЦИЯ\\nfunction add(a, b) {\\n  return a + b;\\n}\\n// Всегда: add(2, 3) => 5. Ничего не меняет.\\n\\n// НЕЧИСТАЯ ФУНКЦИЯ\\nlet counter = 0;\\nfunction increment() {\\n  counter++; // Побочный эффект: изменение внешней переменной\\n}\\n// НЕЧИСТАЯ ФУНКЦИЯ\\nfunction getRandomNumber() {\\n  return Math.random(); // Результат разный при каждом вызове.\\n}\\n// НЕЧИСТАЯ ФУНКЦИЯ\\nfunction saveUser(user) {\\n  fetch(\'/api/users\', { // Побочный эффект: сетевой запрос (IO)\\n    method: \'POST\',\\n    body: JSON.stringify(user)\\n  });\\n}"],[1163,"`Object` — это базовая структура \\"ключ-значение\\", где ключи обычно являются строками или символами. `Map` — это более современная и специализированная структура \\"ключ-значение\\", которая позволяет использовать ключи любого типа (включая объекты), сохраняет порядок элементов и предоставляет удобные методы для работы. `Set` — это коллекция уникальных значений любого типа, которая также сохраняет порядок добавления.","Каждая структура данных предназначена для своих задач.\\nObject (Объект)\\n\\n- Ключи: Только строки или символы. Числа автоматически преобразуются в строки.\\n\\n- Порядок элементов: В современных JS порядок перечисления для строковых ключей соответствует порядку добавления (с некоторыми нюансами для целочисленных ключей), но исторически не гарантировался.\\n\\n- Итерация: Не является итерируемой по умолчанию. Для обхода нужно использовать `Object.keys()`, `Object.values()`, `Object.entries()`.\\n\\n- Размер: Нет встроенного свойства для размера. Нужно вычислять через `Object.keys(obj).length`.\\n\\n- Использование: Идеально для представления структур, у которых ключи известны заранее (например, конфигурация, данные пользователя с фиксированными полями).\\n\\nMap\\n\\n- Ключи: Могут быть любого типа: объекты, функции, примитивы.\\n\\n- Порядок элементов: Гарантированно сохраняет порядок вставки элементов.\\n\\n- Итерация: Является итерируемой. Можно перебирать напрямую с помощью `for...of` или `forEach`.\\n\\n- Размер: Есть встроенное свойство `size`.\\n\\n- Производительность: Лучше подходит для частого добавления и удаления пар ключ-значение.\\n\\n- Использование: Отлично подходит для случаев, когда ключ неизвестен до времени выполнения, или когда ключом должен быть объект (например, для хранения метаданных DOM-элементов).\\n\\nSet\\n\\n- Значения: Коллекция уникальных значений любого типа.\\n\\n- Порядок элементов: Гарантированно сохраняет порядок вставки элементов.\\n\\n- Итерация: Является итерируемой.\\n\\n- Размер: Есть встроенное свойство `size`.\\n\\n- Использование: Идеально для создания списков без дубликатов и для быстрой проверки наличия элемента.\\n\\nВывод\\nИспользуйте `Object` для статических структур с известными строковыми ключами. Используйте `Map`, когда нужны ключи не-строкового типа, частые обновления или важен порядок элементов. Используйте `Set`, когда вам нужно хранить коллекцию уникальных значений.","const map = new Map();\\nconst keyObj = { id: 1 };\\n\\nmap.set(keyObj, \'value associated with object\');\\nmap.set(42, \'answer to everything\');\\n\\nconsole.log(map.get(keyObj)); // \'value associated with object\'\\nconsole.log(map.size); // 2\\n\\nconst set = new Set([1, 2, 3, 3, 4, 4]); // Дубликаты игнорируются\\nset.add(5);\\nconsole.log(set.has(3)); // true\\nconsole.log(set.size); // 4 (значения: 1, 2, 3, 4, 5)"],[1164,"Для оптимизации логирования координат курсора можно использовать троттлинг (throttling) или дебаунсинг (debouncing). Троттлинг гарантирует, что функция будет вызываться не чаще, чем один раз в заданный промежуток времени (например, каждые 100мс), что идеально подходит для отслеживания непрерывного движения. Дебаунсинг откладывает вызов функции до тех пор, пока не пройдет пауза в событиях заданной длительности (например, 250мс), что лучше подходит для логирования конечной позиции курсора.","Событие `mousemove` срабатывает очень часто (десятки раз в секунду), что может создать избыточную нагрузку.\\nThrottling (Троттлинг)\\nТроттлинг ограничивает частоту выполнения функции. Он гарантирует, что функция будет выполняться не более одного раза в указанный период времени.\\n\\n- Принцип: \\"Вызывай функцию не чаще, чем раз в N миллисекунд\\".\\n\\n- Идеально для: Непрерывных потоков событий, где важна регулярность обновлений (например, перетаскивание элементов, отслеживание скролла, резизинг окна).\\n\\nDebouncing (Дебаунсинг)\\nДебаунсинг откладывает выполнение функции до момента, когда между событиями наступит пауза заданной длительности.\\n\\n- Принцип: \\"Вызывай функцию только если после последнего события прошло N миллисекунд, и новых событий не было\\".\\n\\n- Идеально для: Сценариев, где важна только конечная точка после серии быстрых событий (например, поиск по вводу в поле, валидация формы, логирование окончания resize).\\n\\nВывод: Для оптимизации отслеживания курсора используйте троттлинг, если вам нужны регулярные обновления координат во время движения. Используйте дебаунсинг, если вам важно залогировать позицию, в которой пользователь остановил курсор.","function throttle(func, delay) {\\n  let lastCall = 0;\\n  return function (...args) {\\n    const now = Date.now();\\n    if (now - lastCall < delay) {\\n      return; // Игнорируем вызов, если с прошлого вызова прошло мало времени\\n    }\\n    lastCall = now;\\n    return func.apply(this, args);\\n  };\\n}\\n\\nconst throttledLog = throttle((x, y) => {\\n  console.log(`Cursor at: ${x}, ${y}`);\\n}, 100); // Логируем максимум 10 раз в секунду\\n\\ndocument.addEventListener(\'mousemove\', (e) => {\\n  throttledLog(e.clientX, e.clientY);\\n});\\n\\nfunction debounce(func, delay) {\\n  let timeoutId;\\n  return function (...args) {\\n    clearTimeout(timeoutId); // Сбрасываем таймер при каждом новом событии\\n    timeoutId = setTimeout(() => {\\n      func.apply(this, args);\\n    }, delay);\\n  };\\n}\\n\\nconst debouncedLog = debounce((x, y) => {\\n  console.log(`Cursor finally at: ${x}, ${y}`); // Сработает после остановки курсора\\n}, 250);\\n\\ndocument.addEventListener(\'mousemove\', (e) => {\\n  debouncedLog(e.clientX, e.clientY);\\n});"],[1165,"Утечки памяти в JS возникают, когда объекты, которые больше не нужны, не удаляются сборщиком мусора, потому что на них остаются ссылки. Чтобы этого избежать, нужно: 1) Убирать слушатели событий (Event Listeners) с DOM-элементов при их удалении. 2) Не хранить ссылки на DOM-элементы в глобальных переменных или замыканиях дольше необходимого. 3) Осторожно работать с замыканиями и большими объектами, хранящимися в памяти. 4) В современных фреймворках (React, Vue) следить за отпиской от подписок (setInterval, WebSocket) в хуках жизненного цикла размонтирования.","JavaScript использует автоматическое управление памятью с помощью сборщика мусора (Garbage Collector, GC). GC удаляет объекты, на которые больше нет ссылок из \\"живых\\" объектов.\\nРаспространенные причины утечек памяти и их решение:\\n\\n- Забытые таймеры и подписки:\\n\\n- Проблема: `setInterval`, `setTimeout` или подписки на события (например, RxJS) продолжают работать и держать ссылки на объекты, даже если компонент, который их использовал, уже не нужен.\\n\\n- Решение: Всегда очищайте таймеры и отписывайтесь от событий при уничтожении компонента.\\n\\njavascript\\n\\n- Отсоединенные DOM-элементы:\\n\\n- Проблема: Если в переменной сохраняется ссылка на удаленный из DOM элемент, он не сможет быть собранным мусором.\\n\\n- Решение: Обнуляйте ссылки на DOM-элементы после их удаления.\\n\\njavascript\\n\\n- Замыкания (Closures):\\n\\n- Проблема: Замыкание может непреднамеренно удерживать ссылку на большую структуру данных или DOM-элемент, даже если используется лишь малая ее часть.\\n\\n- Решение: Будьте внимательны, что захватывают ваши замыкания. После использования обнуляйте переменные, ссылающиеся на большие объекты.\\n\\n- Глобальные переменные:\\n\\n- Проблема: Объекты, хранящиеся в глобальных переменных, никогда не будут удалены.\\n\\n- Решение: Избегайте глобальных переменных. Используйте локальные переменные и модули.\\n\\n- Кеши без стратегии очистки:\\n\\n- Проблема: Простой кеш в виде объекта или Map, который растет бесконечно.\\n\\n- Решение: Реализуйте стратегии очистки кеша (например, LRU - \\"Least Recently Used\\" или ограничение по размеру).\\n\\nВывод: Для предотвращения утечек памяти выработайте привычку всегда освобождать ресурсы (таймеры, подписки, ссылки на DOM) при разрушении объекта или компонента. Используйте инструменты разработчика (например, Memory Profiler в Chrome DevTools) для поиска и диагностики утечек.","// React пример с useEffect\\nuseEffect(() => {\\n  const intervalId = setInterval(() => {}, 1000);\\n  const subscription = someObservable.subscribe();\\n\\n  // Функция очистки\\n  return () => {\\n    clearInterval(intervalId);\\n    subscription.unsubscribe();\\n  };\\n}, []);\\n\\nlet element = document.getElementById(\'my-element\');\\n// ... работа с элементом\\nelement.remove(); // Удаляем из DOM\\nelement = null;   // Удаляем ссылку из JS"],[1166,"Conditional Types (условные типы) в TypeScript позволяют определять типы, которые выбираются на основе условия, проверяющего другие типы. Они чрезвычайно полезны для создания общих (generic) утилит, которые динамически адаптируются к переданным им типам. Классические примеры — это типы `Exclude<T, U>`, `Extract<T, U>`, `NonNullable<T>`, а также для определения типов возвращаемого значения функций или типов свойств в глубоко вложенных структурах.","Условные типы имеют синтаксис `T extends U ? X : Y`, что читается как \\"если тип T можно присвоить типу U, то результирующим типом будет X, иначе Y\\".\\nОсновные сценарии применения:\\n\\n- Создание общих utility-типов:\\nМногие встроенные в TypeScript утилиты реализованы через условные типы.\\n\\n- Перегрузка функций в дженериках:\\nУсловные типы позволяют выбирать тип на основе входного дженерика.\\n\\n- Извлечение типов из сложных структур:\\nЧасто используется вместе с `infer` для \\"вытаскивания\\" типа из обертки.\\n\\nВывод: Conditional Types — это продвинутый, но невероятно мощный инструмент для создания гибких и выразительных типов, особенно в библиотеках и сложных кодовых базах. Они позволяют типам адаптироваться к условиям, что минимизирует дублирование и повышает безопасность типов.","// Пример: тип Exclude<T, U> исключает из T все типы, которые можно присвоить U\\ntype Exclude<T, U> = T extends U ? never : T;\\ntype T0 = Exclude<\\"a\\" | \\"b\\" | \\"c\\", \\"a\\" | \\"b\\">; // Результат: \\"c\\"\\n\\n// Пример: тип NonNullable<T> исключает null и undefined из T\\ntype NonNullable<T> = T extends null | undefined ? never : T;\\ntype T1 = NonNullable<string | null | undefined>; // Результат: string\\n\\ntype ApiResponse<T extends { id: number }> = T extends { role: \'admin\' }\\n  ? T & { adminNotes: string } // Если у T есть свойство \'role\' со значением \'admin\', добавляем поле\\n  : T; // Иначе возвращаем исходный тип\\n\\ntype User = { id: number; name: string };\\ntype Admin = { id: number; name: string; role: \'admin\' };\\n\\ntype UserResponse = ApiResponse<User>; // { id: number; name: string }\\ntype AdminResponse = ApiResponse<Admin>; // { id: number; name: string; role: \'admin\'; adminNotes: string }\\n\\n// Получаем тип возвращаемого значения функции\\ntype MyReturnType<T> = T extends (...args: any[]) => infer R ? R : any;\\ntype Fn = (x: number) => boolean;\\ntype R = MyReturnType<Fn>; // type R = boolean\\n\\n// Получаем тип элемента массива\\ntype ArrayElementType<T> = T extends (infer U)[] ? U : never;\\ntype Item = ArrayElementType<number[]>; // type Item = number"],[1167,"Event Loop - это механизм, который позволяет JavaScript обрабатывать асинхронные операции, несмотря на то, что язык однопоточный. Он постоянно проверяет очередь задач и выполняет их по порядку. Сначала выполняются все синхронные операции, затем микротаски (promises), и только потом макротаски (setTimeout, setInterval). Это объясняет, почему некоторые операции выполняются не в том порядке, в котором они записаны в коде.","Event Loop - это фундаментальный механизм JavaScript, который обеспечивает выполнение асинхронного кода в однопоточной среде.\\nОсновные компоненты Event Loop\\n\\n- Call Stack - стек вызовов, где выполняются синхронные операции\\n\\n- Callback Queue - очередь обратных вызовов для макротасков\\n\\n- Microtask Queue - очередь для микротасков (promises)\\n\\n- Event Loop - механизм, который координирует работу всех компонентов\\n\\nПриоритет выполнения\\n\\n- Синхронный код выполняется первым и полностью\\n\\n- Микротаски (promises) выполняются сразу после синхронного кода\\n\\n- Макротаски (setTimeout, setInterval) выполняются после микротасков\\n\\nПример выполнения\\n\\nРезультат в консоли:\\n\\nОбъяснение порядка выполнения\\n\\n- Сначала выполняется весь синхронный код: `console.log(\'1\')` и `console.log(\'4\')`\\n\\n- Затем Event Loop проверяет очередь микротасков и выполняет promise: `console.log(\'3\')`\\n\\n- И только после этого выполняются макротаски: `console.log(\'2\')`\\n\\nПрактическое применение\\n\\n- Оптимизация производительности - понимание Event Loop помогает избежать блокировки основного потока\\n\\n- Правильная работа с асинхронными операциями - предсказуемое выполнение кода\\n\\n- Отладка сложных сценариев - понимание порядка выполнения операций\\n\\nВывод: Event Loop критически важен для понимания асинхронности в JavaScript. Используйте микротаски для высокоприоритетных асинхронных операций и макротаски для операций, которые могут быть отложены.","console.log(\'1\');\\n\\nsetTimeout(() => {\\n    console.log(\'2\');\\n}, 0);\\n\\nPromise.resolve().then(() => {\\n    console.log(\'3\');\\n});\\n\\nconsole.log(\'4\');\\n\\n1\\n4\\n3\\n2"],[1168,"Ключевое слово `this` в JavaScript ссылается на объект, в контексте которого выполняется функция. В нестрогом режиме, если функция вызывается без контекста, `this` становится глобальным объектом (window в браузере). В строгом режиме в такой ситуации `this` будет `undefined`. Это помогает избежать случайных изменений глобальных переменных и делает код более безопасным.","Поведение ключевого слова `this` - одна из самых сложных тем в JavaScript, которая значительно отличается между строгим и нестрогим режимами.\\nКак определяется `this`\\nЗначение `this` зависит от контекста вызова функции:\\n\\n- В методах объекта - `this` ссылается на сам объект\\n\\n- В конструкторах - `this` ссылается на создаваемый экземпляр\\n\\n- В обычных функциях - зависит от режима выполнения\\n\\nРазличия в строгом режиме\\nНестрогий режим\\n\\nСтрогий режим\\n\\nОсновные случаи определения `this`\\n1. Вызов метода объекта\\n\\n2. Вызов функции-конструктора\\n\\n3. Использование call, apply, bind\\n\\nПрактические рекомендации\\n\\n- Всегда используйте строгий режим для предотвращения ошибок\\n\\n- Используйте стрелочные функции когда нужно сохранить контекст\\n\\n- Явно привязывайте контекст с помощью bind, call, apply когда необходимо\\n\\nВывод: Строгий режим делает поведение `this` более предсказуемым и безопасным, предотвращая случайные обращения к глобальному объекту. Это особенно важно в больших проектах и при работе с модулями.","function showThis() {\\n    console.log(this);\\n}\\n\\nshowThis(); // Window (в браузере) или global (в Node.js)\\n\\n\'use strict\';\\n\\nfunction showThis() {\\n    console.log(this);\\n}\\n\\nshowThis(); // undefined\\n\\nconst obj = {\\n    name: \'Test\',\\n    showThis() {\\n        console.log(this.name);\\n    }\\n};\\n\\nobj.showThis(); // \\"Test\\" - в обоих режимах\\n\\nfunction Person(name) {\\n    this.name = name;\\n}\\n\\nconst person = new Person(\'John\');\\nconsole.log(person.name); // \\"John\\" - в обоих режимах\\n\\nfunction showName() {\\n    console.log(this.name);\\n}\\n\\nconst obj = { name: \'Alice\' };\\n\\nshowName.call(obj); // \\"Alice\\" - в обоих режимах"],[1169,"Строгий режим - это специальный режим в JavaScript, который делает код более безопасным и предотвращает распространенные ошибки. Он запрещает некоторые синтаксические конструкции, которые считаются проблемными, и изменяет поведение некоторых операций. Например, в строгом режиме нельзя использовать необъявленные переменные, удалять неудаляемые свойства или дублировать параметры функции. Это помогает писать более качественный и надежный код.","Строгий режим (strict mode) представляет собой ограниченную версию JavaScript, которая обеспечивает лучшую проверку ошибок и безопасность.\\nАктивация строгого режима\\n\\n- Для всего файла - добавьте `\'use strict\';` в начало файла\\n\\n- Для отдельной функции - добавьте `\'use strict\';` в начало функции\\n\\nОсновные отличия строгого режима\\n1. Обработка переменных\\nНестрогий режим:\\n\\nСтрогий режим:\\n\\n2. Поведение `this`\\nНестрогий режим:\\n\\nСтрогий режим:\\n\\n3. Ограничения на синтаксис\\n\\n- Запрет на дублирование параметров\\n\\n- Запрет на использование зарезервированных слов как имен переменных\\n\\n- Запрет на удаление неудаляемых свойств\\n\\nПреимущества строгого режима\\n\\n- Более строгая проверка ошибок - многие ошибки становятся исключениями\\n\\n- Улучшенная производительность - некоторые оптимизации доступны только в строгом режиме\\n\\n- Лучшая безопасность - предотвращает случайные действия с глобальным объектом\\n\\nПрактическое применение\\n\\n- Современная разработка - большинство фреймворков используют строгий режим по умолчанию\\n\\n- Модульные системы - ES6 модули автоматически работают в строгом режиме\\n\\n- Код-стайл и линтеры - рекомендуют всегда использовать строгий режим\\n\\nВывод: Строгий режим следует использовать всегда в новых проектах, так как он помогает избежать распространенных ошибок и делает код более безопасным и предсказуемым.","x = 10; // Создает глобальную переменную\\nconsole.log(x); // 10\\n\\n\'use strict\';\\nx = 10; // ReferenceError: x is not defined\\n\\nfunction showThis() {\\n    console.log(this); // Window или global\\n}\\nshowThis();\\n\\n\'use strict\';\\nfunction showThis() {\\n    console.log(this); // undefined\\n}\\nshowThis();"],[1170,"В JavaScript есть несколько способов создания объектов. Самый простой - использовать литерал объекта `{}`. Функции-конструкторы создают объекты через ключевое слово `new`. Классы ES6 предоставляют современный синтаксис для создания объектов. `Object.create()` позволяет создавать объекты с указанным прототипом. Фабричные функции возвращают новые объекты без использования `new`. Каждый метод имеет свои особенности применения.","Способы создания объектов в JavaScript\\nJavaScript предоставляет несколько методов для создания объектов, каждый со своей спецификой:\\n1. Литерал объекта\\nСамый простой и распространенный способ:\\njavascript\\n\\n2. Функция-конструктор\\nИспользуется с оператором `new`:\\njavascript\\n\\n3. Классы ES6\\nСовременный синтаксис для создания объектов:\\njavascript\\n\\n4. Object.create()\\nСоздает объект с указанным прототипом:\\njavascript\\n\\n5. Фабричная функция\\nФункция, возвращающая новый объект:\\njavascript\\n\\nВывод: Выбор метода зависит от конкретной задачи - литералы для простых объектов, классы для сложных иерархий, фабричные функции для гибкого создания.","const person = {\\n  name: \\"Иван\\",\\n  age: 30,\\n  greet() {\\n    console.log(`Привет, я ${this.name}`);\\n  }\\n};\\n\\nfunction Person(name, age) {\\n  this.name = name;\\n  this.age = age;\\n}\\nconst person = new Person(\\"Иван\\", 30);\\n\\nclass Person {\\n  constructor(name, age) {\\n    this.name = name;\\n    this.age = age;\\n  }\\n}\\nconst person = new Person(\\"Иван\\", 30);\\n\\nconst personProto = {\\n  greet() {\\n    console.log(`Привет, я ${this.name}`);\\n  }\\n};\\nconst person = Object.create(personProto);\\nperson.name = \\"Иван\\";\\nperson.age = 30;\\n\\nfunction createPerson(name, age) {\\n  return {\\n    name,\\n    age,\\n    greet() {\\n      console.log(`Привет, я ${this.name}`);\\n    }\\n  };\\n}\\nconst person = createPerson(\\"Иван\\", 30);"],[1171,"Функция-конструктор - это обычная функция, которая используется с оператором `new` для создания объектов. Она определяет структуру и начальное состояние создаваемых объектов. При вызове с `new` функция создает новый объект, устанавливает его прототип и выполняет инициализацию через ключевое слово `this`.","Функция-конструктор в JavaScript\\nФункция-конструктор - это специальный тип функции, который используется для создания и инициализации объектов.\\nОпределение функции-конструктора\\nФункция-конструктор объявляется как обычная функция, но имеет определенные соглашения:\\n\\nОсобенности функций-конструкторов\\n\\n- Именование: По соглашению начинаются с заглавной буквы\\n\\n- Использование: Вызываются с оператором `new`\\n\\n- Возвращаемое значение: Обычно не возвращают значение явно\\n\\n- Контекст: `this` внутри функции ссылается на создаваемый объект\\n\\nПроцесс создания объекта\\nПри вызове функции с `new` происходит следующее:\\n\\n- Создается новый пустой объект\\n\\n- Устанавливается прототип объекта\\n\\n- Вызывается функция-конструктор с `this`, указывающим на новый объект\\n\\n- Возвращается созданный объект\\n\\nПример использования\\n\\nДобавление методов в прототип\\nДля оптимизации памяти методы лучше добавлять в прототип:\\n\\nВывод: Функции-конструкторы используются для создания множества объектов с одинаковой структурой. Они обеспечивают переиспользование кода и являются основой для объектно-ориентированного программирования в JavaScript до появления классов.","function Person(name, age) {\\n  // Свойства устанавливаются через this\\n  this.name = name;\\n  this.age = age;\\n  \\n  // Методы также могут добавляться через this\\n  this.greet = function() {\\n    console.log(`Привет, я ${this.name}`);\\n  };\\n}\\n\\n// Создание объектов через конструктор\\nconst person1 = new Person(\'Иван\', 30);\\nconst person2 = new Person(\'Мария\', 25);\\n\\nconsole.log(person1.name); // \\"Иван\\"\\nconsole.log(person2.age);  // 25\\n\\nfunction Person(name, age) {\\n  this.name = name;\\n  this.age = age;\\n}\\n\\n// Методы добавляются в прототип\\nPerson.prototype.greet = function() {\\n  console.log(`Привет, я ${this.name}`);\\n};"],[1172,"При вызове функции-конструктора с оператором `new`, значение `this` автоматически устанавливается на вновь созданный объект. Этот объект создается неявно до выполнения кода конструктора. Все свойства и методы, добавленные через `this`, становятся частью создаваемого объекта.","Поведение this в функции-конструкторе\\nЗначение `this` внутри функции-конструктора определяется способом вызова функции.\\nКонтекст this при вызове с new\\nКогда функция вызывается с оператором `new`, происходит следующее:\\njavascript\\n\\nМеханизм работы new\\nОператор `new` выполняет четыре шага:\\n\\n- Создание объекта: Создается новый пустой объект\\n\\n- Установка прототипа: Прототип объекта связывается с свойством `prototype` конструктора\\n\\n- Привязка this: `this` связывается с созданным объектом\\n\\n- Возврат объекта: Если функция не возвращает объект, возвращается `this`\\n\\nОтличие от обычного вызова\\nБез оператора `new` поведение `this` отличается:\\njavascript\\n\\nСтрогий режим\\nВ строгом режиме поведение становится более предсказуемым:\\njavascript\\n\\nПроверка вызова с new\\nДля защиты от вызова без `new` можно использовать проверки:\\njavascript\\n\\nВывод: В функции-конструкторе `this` всегда ссылается на создаваемый объект при вызове с `new`. Понимание этого механизма важно для правильного использования конструкторов и избежания ошибок.","function Car(brand, model) {\\n  // this автоматически ссылается на новый объект\\n  this.brand = brand;\\n  this.model = model;\\n  this.year = 2024;\\n}\\n\\nconst myCar = new Car(\'Toyota\', \'Camry\');\\n\\nfunction Car(brand) {\\n  this.brand = brand;\\n}\\n\\n// С new - this ссылается на новый объект\\nconst car1 = new Car(\'Toyota\');\\nconsole.log(car1.brand); // \\"Toyota\\"\\n\\n// Без new - this зависит от контекста (в строгом режиме undefined)\\nconst car2 = Car(\'Honda\'); // Ошибка или добавление в глобальный объект\\n\\n\'use strict\';\\n\\nfunction Car(brand) {\\n  this.brand = brand;\\n}\\n\\nconst car = new Car(\'Toyota\'); // Работает\\nCar(\'Honda\'); // Ошибка: Cannot set property \'brand\' of undefined\\n\\nfunction Car(brand) {\\n  if (!(this instanceof Car)) {\\n    throw new Error(\'Конструктор Car должен вызываться с new\');\\n  }\\n  this.brand = brand;\\n}"],[1173,"При вызове функции-конструктора с оператором `new`, `this` равен вновь созданному объекту. Если функция вызывается без `new`, значение `this` зависит от контекста вызова - в строгом режиме это `undefined`, в нестрогом - глобальный объект (window в браузере).","Значение this при вызове функции-конструктора\\nЗначение `this` зависит исключительно от того, как вызывается функция-конструктор.\\nВызов с оператором new\\nПри корректном использовании с `new`:\\njavascript\\n\\nВызов без оператора new\\nПри обычном вызове функции:\\njavascript\\n\\nПрактические примеры\\nРассмотрим различные сценарии:\\njavascript\\n\\nЗащита от неправильного вызова\\nМожно добавить проверку для безопасного использования:\\njavascript\\n\\nСовременный подход с классами\\nВ классах ES6 вызов без `new` всегда приводит к ошибке:\\njavascript\\n\\nВывод: `this` в функции-конструкторе равен новому объекту только при вызове с `new`. Всегда используйте `new` с конструкторами или применяйте защитные проверки для избежания ошибок.","function Person(name) {\\n  // this ссылается на новый объект\\n  this.name = name;\\n  console.log(this); // Person { name: ... }\\n}\\n\\nconst person = new Person(\'Иван\');\\n\\nfunction Person(name) {\\n  this.name = name;\\n  console.log(this); // Зависит от контекста\\n}\\n\\n// В нестрогом режиме\\nPerson(\'Иван\'); // this = global/window объект\\n\\n// В строгом режиме\\n\'use strict\';\\nPerson(\'Иван\'); // this = undefined (будет ошибка)\\n\\n// Пример 1: Обычный вызов с new\\nfunction Car(brand) {\\n  this.brand = brand;\\n  console.log(this instanceof Car); // true\\n}\\nconst car = new Car(\'Toyota\');\\n\\n// Пример 2: Вызов без new (ошибка)\\nfunction Bike(model) {\\n  this.model = model;\\n}\\n// Bike(\'Yamaha\'); // Ошибка в строгом режиме\\n\\n// Пример 3: Вызов метода как конструктора\\nconst obj = {\\n  createCar: function(brand) {\\n    this.brand = brand;\\n  }\\n};\\n\\nobj.createCar(\'BMW\'); // this = obj\\nnew obj.createCar(\'Audi\'); // this = новый объект\\n\\nfunction SafeConstructor(value) {\\n  // Проверяем, вызвана ли функция с new\\n  if (!(this instanceof SafeConstructor)) {\\n    // Если нет, вызываем себя правильно\\n    return new SafeConstructor(value);\\n  }\\n  \\n  this.value = value;\\n}\\n\\n// Оба вызова работают одинаково\\nconst obj1 = new SafeConstructor(\'test\');\\nconst obj2 = SafeConstructor(\'test\'); // Автоматически исправляется\\n\\nclass Person {\\n  constructor(name) {\\n    this.name = name;\\n  }\\n}\\n\\nconst person = new Person(\'Иван\'); // OK\\n// Person(\'Иван\'); // Ошибка: Class constructor cannot be invoked without \'new\'"],[1174,"Нет, функция-конструктор создает объект не всегда. Если функция вызывается без оператора `new`, объект не создается. Также, если конструктор явно возвращает объект, то созданный автоматически объект игнорируется. Только при вызове с `new` и без возврата объекта создается новый экземпляр.","Условия создания объектов функциями-конструкторами\\nФункция-конструктор создает объект только при определенных условиях.\\nСтандартное поведение с new\\nПри нормальном использовании с оператором `new`:\\njavascript\\n\\nВызов без new\\nБез оператора `new` объект не создается:\\njavascript\\n\\nЯвный возврат примитива\\nЕсли возвращается примитивное значение, оно игнорируется:\\njavascript\\n\\nЯвный возврат объекта\\nЕсли возвращается объект, он заменяет созданный объект:\\njavascript\\n\\nУсловия создания объекта\\nОбъект создается когда:\\n\\n- Функция вызывается с оператором `new`\\n\\n- Функция не возвращает объект (или возвращает примитив)\\n\\nПрактический пример с проверкой\\njavascript\\n\\nВывод: Функция-конструктор создает объект только при вызове с `new` и когда не возвращает другой объект. Понимание этих условий помогает избежать неожиданного поведения в коде.","function Person(name) {\\n  this.name = name;\\n  // Не возвращаем значение явно\\n}\\n\\nconst person = new Person(\'Иван\');\\nconsole.log(person instanceof Person); // true - объект создан\\n\\nfunction Person(name) {\\n  this.name = name;\\n}\\n\\nconst result = Person(\'Иван\'); // Вызов без new\\nconsole.log(result); // undefined - объект не создан\\n\\nfunction Person(name) {\\n  this.name = name;\\n  return 42; // Примитив игнорируется\\n}\\n\\nconst person = new Person(\'Иван\');\\nconsole.log(person.name); // \\"Иван\\" - объект создан\\n\\nfunction Person(name) {\\n  this.name = name;\\n  return { custom: \'object\' }; // Объект подменяет созданный\\n}\\n\\nconst person = new Person(\'Иван\');\\nconsole.log(person); // { custom: \'object\' } - не Person\\nconsole.log(person instanceof Person); // false\\n\\nfunction Car(brand) {\\n  // Проверяем, вызвана ли с new\\n  if (!(this instanceof Car)) {\\n    console.log(\'Объект не создан - вызвано без new\');\\n    return;\\n  }\\n  \\n  this.brand = brand;\\n}\\n\\nconst car1 = new Car(\'Toyota\'); // Объект создан\\nconst car2 = Car(\'Honda\');      // Объект не создан"],[1175,"Если функция-конструктор возвращает примитивное значение (число, строку, boolean, null, undefined, символ), это возвращаемое значение игнорируется. В результате все равно возвращается вновь созданный объект, на который ссылается `this`. Механизм `new` переопределяет возврат примитивов.","Возврат примитивных значений из конструктора\\nКогда функция-конструктор возвращает примитивное значение, это не влияет на результат создания объекта.\\nИгнорирование примитивных возвращаемых значений\\nВсе примитивные типы игнорируются:\\njavascript\\n\\nПрактические примеры\\nРассмотрим различные сценарии с возвратом примитивов:\\njavascript\\n\\nСравнение с возвратом объекта\\nВ отличие от примитивов, возврат объекта изменяет результат:\\njavascript\\n\\nПочему примитивы игнорируются\\nМеханизм оператора `new` специально игнорирует примитивные возвращаемые значения чтобы:\\n\\n- Сохранять консистентность создания объектов\\n\\n- Предотвращать случайные ошибки\\n\\n- Обеспечивать ожидаемое поведение конструкторов\\n\\nВывод: Возврат примитивных значений из функции-конструктора игнорируется - всегда возвращается объект, созданный оператором `new`. Это поведение гарантирует, что конструкторы всегда возвращают экземпляры объектов.","function Person(name) {\\n  this.name = name;\\n  \\n  // Все эти возвраты будут проигнорированы\\n  return 42;                    // число\\n  return \'строка\';              // строка\\n  return true;                  // boolean\\n  return null;                  // null\\n  return undefined;             // undefined\\n  return Symbol(\'символ\');      // символ\\n}\\n\\nconst person = new Person(\'Иван\');\\nconsole.log(person.name); // \\"Иван\\" - объект создан\\nconsole.log(person instanceof Person); // true\\n\\n// Пример 1: Возврат числа\\nfunction Car(brand) {\\n  this.brand = brand;\\n  return 100; // Игнорируется\\n}\\n\\nconst car = new Car(\'Toyota\');\\nconsole.log(car.brand); // \\"Toyota\\"\\nconsole.log(car); // Car { brand: \\"Toyota\\" }\\n\\n// Пример 2: Возврат undefined (явный и неявный)\\nfunction Bike(model) {\\n  this.model = model;\\n  // Неявный возврат undefined - объект создается\\n}\\n\\nfunction Boat(name) {\\n  this.name = name;\\n  return undefined; // Явный возврат - также игнорируется\\n}\\n\\nconst bike = new Bike(\'Yamaha\');\\nconst boat = new Boat(\'Ладья\');\\nconsole.log(bike instanceof Bike); // true\\nconsole.log(boat instanceof Boat); // true\\n\\nfunction TestPrimitive() {\\n  this.value = \'original\';\\n  return 123; // Примитив - игнорируется\\n}\\n\\nfunction TestObject() {\\n  this.value = \'original\';\\n  return { value: \'custom\' }; // Объект - заменяет результат\\n}\\n\\nconst test1 = new TestPrimitive();\\nconst test2 = new TestObject();\\n\\nconsole.log(test1.value); // \\"original\\"\\nconsole.log(test2.value); // \\"custom\\""],[1176,"Если функция-конструктор возвращает объект, то возвращается именно этот объект, а не автоматически созданный через `this`. Возвращаемый объект полностью заменяет объект, на который ссылается `this`. Это позволяет создавать фабричные методы и контролировать процесс создания объектов.","Возврат объектов из функций-конструкторов\\nКогда функция-конструктор возвращает объект, это кардинально меняет стандартное поведение.\\nПодмена созданного объекта\\nВозвращаемый объект заменяет объект, созданный оператором `new`:\\njavascript\\n\\nСравнение с обычным поведением\\nРазница между возвратом объекта и примитива:\\njavascript\\n\\nПрактическое применение\\nЭто поведение используется в различных паттернах:\\n1. Фабричный метод\\njavascript\\n\\n2. Кэширование экземпляров\\njavascript\\n\\n3. Декораторы и обертки\\njavascript\\n\\nОграничения и предостережения\\nВозврат объектов из конструкторов может быть неочевидным:\\njavascript\\n\\nСовременная альтернатива\\nВместо возврата объектов из конструкторов лучше использовать фабричные функции:\\njavascript\\n\\nВывод: При возврате объекта из функции-конструктора возвращается именно этот объект, а не автоматически созданный. Это мощная возможность, но ее следует использовать осознанно, так как она нарушает стандартное ожидание поведения конструкторов.","function Person(name) {\\n  this.name = name; // Это свойство будет потеряно\\n  \\n  // Возвращаемый объект заменяет созданный\\n  return { customName: \'Кастомное имя\' };\\n}\\n\\nconst person = new Person(\'Иван\');\\nconsole.log(person); // { customName: \'Кастомное имя\' }\\nconsole.log(person.name); // undefined\\nconsole.log(person instanceof Person); // false\\n\\nfunction NormalConstructor() {\\n  this.property = \'значение\';\\n  // Не возвращаем ничего (или возвращаем примитив)\\n}\\n\\nfunction ObjectReturningConstructor() {\\n  this.property = \'значение\';\\n  return { customProperty: \'кастомное значение\' };\\n}\\n\\nconst normal = new NormalConstructor();\\nconst custom = new ObjectReturningConstructor();\\n\\nconsole.log(normal.property); // \\"значение\\"\\nconsole.log(custom.property); // undefined\\nconsole.log(custom.customProperty); // \\"кастомное значение\\"\\n\\nfunction CreateUser(type) {\\n  if (type === \'admin\') {\\n    return { role: \'admin\', permissions: [\'read\', \'write\', \'delete\'] };\\n  } else {\\n    return { role: \'user\', permissions: [\'read\'] };\\n  }\\n}\\n\\nconst admin = new CreateUser(\'admin\');\\nconst user = new CreateUser(\'user\');\\n\\nfunction Logger(name) {\\n  // Если экземпляр уже существует, возвращаем его\\n  if (Logger.instances[name]) {\\n    return Logger.instances[name];\\n  }\\n  \\n  this.name = name;\\n  Logger.instances[name] = this;\\n}\\n\\nLogger.instances = {};\\n\\nconst logger1 = new Logger(\'app\');\\nconst logger2 = new Logger(\'app\');\\nconsole.log(logger1 === logger2); // true - тот же объект\\n\\nfunction Observable(target) {\\n  const observers = [];\\n  \\n  return {\\n    subscribe: function(observer) {\\n      observers.push(observer);\\n    },\\n    notify: function(data) {\\n      observers.forEach(observer => observer(data));\\n    },\\n    // Сохраняем оригинальный target\\n    target: target\\n  };\\n}\\n\\nconst observable = new Observable({ data: \'test\' });\\n\\nfunction ConfusingConstructor() {\\n  this.expected = \'ожидаемое свойство\';\\n  return { unexpected: \'неожиданное свойство\' };\\n}\\n\\nconst obj = new ConfusingConstructor();\\n// Разработчик может ожидать obj.expected, но получит obj.unexpected\\n\\n// Более понятная альтернатива\\nfunction createUser(type) {\\n  if (type === \'admin\') {\\n    return { role: \'admin\', permissions: [\'read\', \'write\', \'delete\'] };\\n  } else {\\n    return { role: \'user\', permissions: [\'read\'] };\\n  }\\n}\\n\\n// Вызывается без new\\nconst admin = createUser(\'admin\');"],[1177,"MVC, MVVM и MVP - это архитектурные паттерны для разделения ответственности в приложениях. MVC разделяет на Model (данные), View (интерфейс) и Controller (логика). MVP добавляет Presenter как посредник. MVVM использует ViewModel для двустороннего связывания данных. Основные различия в способе взаимодействия между компонентами и уровне связности.","Архитектурные паттерны проектирования\\nЭти паттерны помогают организовать код приложения, разделяя ответственность между различными компонентами.\\n1. MVC (Model-View-Controller)\\nСтруктура:\\n\\n- Model - данные и бизнес-логика\\n\\n- View - отображение данных, пользовательский интерфейс\\n\\n- Controller - обработка пользовательского ввода, посредник между Model и View\\n\\nВзаимодействие:\\ntext\\n\\nПример реализации:\\njavascript\\n\\n2. MVP (Model-View-Presenter)\\nСтруктура:\\n\\n- Model - данные и бизнес-логика\\n\\n- View - пассивный интерфейс, делегирует действия Presenter\\n\\n- Presenter - получает данные от Model и подготавливает для View\\n\\nВзаимодействие:\\ntext\\n\\nОсобенности:\\n\\n- View пассивна, не знает о Model\\n\\n- Presenter управляет View и обрабатывает события\\n\\n- Более тесная связь между View и Presenter\\n\\nПример реализации:\\njavascript\\n\\n3. MVVM (Model-View-ViewModel)\\nСтруктура:\\n\\n- Model - данные и бизнес-логика\\n\\n- View - отображение, привязка к ViewModel\\n\\n- ViewModel - представление данных для View, двустороннее связывание\\n\\nВзаимодействие:\\ntext\\n\\nОсобенности:\\n\\n- Двустороннее связывание данных (data binding)\\n\\n- ViewModel не знает о View\\n\\n- Автоматическое обновление View при изменении ViewModel\\n\\nПример реализации (Vue.js):\\njavascript\\n\\nСравнение паттернов\\nУровень связности:\\n\\n- MVC: View знает о Model\\n\\n- MVP: View не знает о Model, тесная связь с Presenter\\n\\n- MVVM: View знает о ViewModel, но не о Model\\n\\nТестируемость:\\n\\n- MVP: Легче всего тестировать (Presenter изолирован)\\n\\n- MVVM: ViewModel легко тестируется\\n\\n- MVC: Сложнее тестировать из-за связности\\n\\nПрименение:\\n\\n- MVC: Традиционные веб-приложения (Ruby on Rails, Spring)\\n\\n- MVP: Приложения с сложной бизнес-логикой\\n\\n- MVVM: Современные SPA (Angular, Vue.js, WPF)\\n\\nВывод: Выбор паттерна зависит от сложности приложения, требований к тестируемости и предпочтений команды. MVC подходит для простых приложений, MVP - для лучшей тестируемости, MVVM - для приложений с богатым UI и двусторонним связыванием.","Пользователь → Controller → Model → View → Пользователь\\n\\n// Model\\nclass UserModel {\\n  constructor() {\\n    this.users = [];\\n  }\\n  \\n  addUser(user) {\\n    this.users.push(user);\\n  }\\n  \\n  getUsers() {\\n    return this.users;\\n  }\\n}\\n\\n// View\\nclass UserView {\\n  displayUsers(users) {\\n    users.forEach(user => {\\n      console.log(`User: ${user.name}, Email: ${user.email}`);\\n    });\\n  }\\n}\\n\\n// Controller\\nclass UserController {\\n  constructor(model, view) {\\n    this.model = model;\\n    this.view = view;\\n  }\\n  \\n  addUser(name, email) {\\n    this.model.addUser({ name, email });\\n    this.updateView();\\n  }\\n  \\n  updateView() {\\n    const users = this.model.getUsers();\\n    this.view.displayUsers(users);\\n  }\\n}\\n\\nПользователь → View → Presenter → Model → Presenter → View\\n\\n// View interface\\nclass IUserView {\\n  showUsers(users) {}\\n  getUserInput() {}\\n}\\n\\n// Presenter\\nclass UserPresenter {\\n  constructor(model, view) {\\n    this.model = model;\\n    this.view = view;\\n  }\\n  \\n  onAddUserButtonClick() {\\n    const userData = this.view.getUserInput();\\n    this.model.addUser(userData);\\n    this.updateView();\\n  }\\n  \\n  updateView() {\\n    const users = this.model.getUsers();\\n    this.view.showUsers(users);\\n  }\\n}\\n\\nView ↔ ViewModel ↔ Model\\n\\n// ViewModel (Vue instance)\\nnew Vue({\\n  el: \'#app\',\\n  data: {\\n    users: [],\\n    newUser: { name: \'\', email: \'\' }\\n  },\\n  methods: {\\n    addUser() {\\n      this.users.push({ ...this.newUser });\\n      this.newUser = { name: \'\', email: \'\' };\\n    }\\n  }\\n});\\n\\n// View (HTML template)\\n/*\\n<div id=\\"app\\">\\n  <input v-model=\\newUser.name\\" placeholder=\\"Name\\">\\n  <input v-model=\\newUser.email\\" placeholder=\\"Email\\">\\n  <button @click=\\"addUser\\">Add User</button>\\n  <div v-for=\\"user in users\\">\\n    {{ user.name }} - {{ user.email }}\\n  </div>\\n</div>\\n*/"],[1178,"JavaScript различает примитивы (числа, строки, boolean, null, undefined, symbol, bigint) и объекты. Примитивы хранятся по значению, иммутабельны и сравниваются по значению. Объекты хранятся по ссылке, мутабельны и сравниваются по ссылке. Примитивы могут временно вести себя как объекты через обертки.","Работа с примитивами и объектами в JavaScript\\nПонимание различий между примитивами и объектами критически важно для написания корректного JavaScript кода.\\nПримитивные типы\\nJavaScript имеет 7 примитивных типов:\\njavascript\\n\\nОбъекты\\nВсе остальные значения являются объектами:\\njavascript\\n\\nКлючевые различия в поведении\\n1. Хранение в памяти\\nПримитивы хранятся по значению:\\njavascript\\n\\nОбъекты хранятся по ссылке:\\njavascript\\n\\n2. Сравнение\\nПримитивы сравниваются по значению:\\njavascript\\n\\nОбъекты сравниваются по ссылке:\\njavascript\\n\\n3. Мутабельность\\nПримитивы иммутабельны:\\njavascript\\n\\nОбъекты мутабельны:\\njavascript\\n\\n4. Использование методов\\nПримитивы используют обертки:\\njavascript\\n\\nОбъекты используют методы напрямую:\\njavascript\\n\\nПрактические примеры различий\\n1. Передача в функции\\njavascript\\n\\n2. Копирование\\njavascript\\n\\n3. Проверка типов\\njavascript\\n\\nОсобые случаи\\nОберточные объекты\\njavascript\\n\\nАвтоматическая упаковка\\njavascript\\n\\nВывод: Примитивы и объекты в JavaScript имеют фундаментальные различия в хранении, сравнении, мутабельности и поведении. Понимание этих различий помогает избежать распространенных ошибок и писать более эффективный код.","// Примитивные значения\\nconst number = 42;           // number\\nconst string = \\"hello\\";      // string  \\nconst boolean = true;        // boolean\\nconst nullValue = null;      // null\\nconst undefinedValue = undefined; // undefined\\nconst symbol = Symbol(\\"id\\"); // symbol\\nconst bigInt = 9007199254740991n; // bigint\\n\\n// Объекты\\nconst object = { key: \\"value\\" };\\nconst array = [1, 2, 3];\\nconst functionObj = function() {};\\nconst date = new Date();\\nconst regex = /pattern/;\\n\\nlet a = 10;\\nlet b = a; // b получает копию значения\\na = 20;\\nconsole.log(a); // 20\\nconsole.log(b); // 10 - не изменилось\\n\\nlet obj1 = { value: 10 };\\nlet obj2 = obj1; // obj2 получает ссылку на тот же объект\\nobj1.value = 20;\\nconsole.log(obj1.value); // 20\\nconsole.log(obj2.value); // 20 - изменилось тоже!\\n\\nconst a = \\"hello\\";\\nconst b = \\"hello\\";\\nconsole.log(a === b); // true - одинаковые значения\\n\\nconst num1 = 5;\\nconst num2 = 5;\\nconsole.log(num1 === num2); // true\\n\\nconst obj1 = { value: 10 };\\nconst obj2 = { value: 10 };\\nconst obj3 = obj1;\\n\\nconsole.log(obj1 === obj2); // false - разные ссылки\\nconsole.log(obj1 === obj3); // true - одинаковые ссылки\\n\\nlet str = \\"hello\\";\\nstr[0] = \\"H\\"; // Не сработает\\nconsole.log(str); // \\"hello\\" - не изменилось\\n\\n// Создается новая строка\\nstr = str.toUpperCase();\\nconsole.log(str); // \\"HELLO\\" - новый примитив\\n\\nconst obj = { value: 10 };\\nobj.value = 20; // Изменяет существующий объект\\nobj.newProp = \\new\\"; // Добавляет свойство\\nconsole.log(obj); // { value: 20, newProp: \\new\\" }\\n\\nconst str = \\"hello\\";\\nconsole.log(str.toUpperCase()); // \\"HELLO\\"\\n\\n// Что происходит под капотом:\\n// 1. Создается временный String объект\\n// 2. Вызывается метод toUpperCase()\\n// 3. Временный объект удаляется\\n\\nconst arr = [1, 2, 3];\\narr.push(4); // Метод вызывается напрямую\\nconsole.log(arr); // [1, 2, 3, 4]\\n\\n// Примитив - передается по значению\\nfunction modifyPrimitive(x) {\\n  x = x * 2;\\n  return x;\\n}\\n\\nlet num = 5;\\nmodifyPrimitive(num);\\nconsole.log(num); // 5 - не изменился\\n\\n// Объект - передается по ссылке\\nfunction modifyObject(obj) {\\n  obj.value = obj.value * 2;\\n}\\n\\nlet myObj = { value: 5 };\\nmodifyObject(myObj);\\nconsole.log(myObj.value); // 10 - изменился\\n\\n// Поверхностное копирование объектов\\nconst original = { a: 1, b: { c: 2 } };\\nconst shallowCopy = { ...original };\\n\\nshallowCopy.a = 10; // Не влияет на original\\nshallowCopy.b.c = 20; // Влияет на original!\\nconsole.log(original.b.c); // 20\\n\\n// Глубокое копирование\\nconst deepCopy = JSON.parse(JSON.stringify(original));\\ndeepCopy.b.c = 30;\\nconsole.log(original.b.c); // 20 - не изменилось\\n\\n// typeof для примитивов\\nconsole.log(typeof \\"hello\\");    // \\"string\\"\\nconsole.log(typeof 42);         // \\number\\"\\nconsole.log(typeof true);       // \\"boolean\\"\\nconsole.log(typeof undefined);  // \\"undefined\\"\\nconsole.log(typeof Symbol());   // \\"symbol\\"\\nconsole.log(typeof 42n);        // \\"bigint\\"\\nconsole.log(typeof null);       // \\"object\\" (известная ошибка)\\n\\n// typeof для объектов\\nconsole.log(typeof {});         // \\"object\\"\\nconsole.log(typeof []);         // \\"object\\"\\nconsole.log(typeof function(){});// \\"function\\"\\n\\n// Явное создание оберток\\nconst strPrimitive = \\"hello\\";\\nconst strObject = new String(\\"hello\\");\\n\\nconsole.log(typeof strPrimitive); // \\"string\\"\\nconsole.log(typeof strObject);    // \\"object\\"\\nconsole.log(strPrimitive === strObject); // false\\n\\n// JavaScript автоматически упаковывает примитивы\\nconst str = \\"hello\\";\\nconsole.log(str.length); // 5 - временный String объект\\n\\n// Эквивалентно:\\nconst tempStr = new String(str);\\nconsole.log(tempStr.length);\\ntempStr = null; // Удаление временного объекта"],[1179,"В JavaScript существуют примитивные типы (числа, строки, булевы значения) и объектные структуры данных. Основные структуры включают массивы для упорядоченных коллекций, объекты для хранения ключ-значение пар, множества для уникальных значений и карты для любых типов ключей. Каждая структура имеет свои методы и оптимальные сценарии использования.","Примитивные типы данных\\nБазовые примитивы\\n\\n- Number: целые и дробные числа\\n\\n- String: текстовые данные\\n\\n- Boolean: логические значения true/false\\n\\n- Undefined: неопределенное значение\\n\\n- Null: явное отсутствие значения\\n\\n- Symbol: уникальные идентификаторы\\n\\n- BigInt: большие целые числа\\n\\nОбъектные структуры данных\\nArray (Массив)\\njavascript\\n\\nХарактеристики:\\n\\n- Упорядоченная коллекция элементов\\n\\n- Индексация с 0\\n\\n- Динамический размер\\n\\n- Гетерогенные элементы (разные типы)\\n\\nObject (Объект)\\njavascript\\n\\nХарактеристики:\\n\\n- Коллекция ключ-значение\\n\\n- Ключи - строки или Symbol\\n\\n- Не гарантирует порядок свойств\\n\\n- Прототипное наследование\\n\\nSet (Множество)\\njavascript\\n\\nХарактеристики:\\n\\n- Коллекция уникальных значений\\n\\n- Быстрая проверка наличия элемента\\n\\n- Сохраняет порядок добавления\\n\\nMap (Карта)\\njavascript\\n\\nХарактеристики:\\n\\n- Коллекция ключ-значение с любыми типами ключей\\n\\n- Сохраняет порядок добавления\\n\\n- Лучшая производительность для частых операций добавления/удаления\\n\\nСпециализированные структуры\\nWeakMap и WeakSet\\n\\n- Слабые ссылки (не предотвращают сборку мусора)\\n\\n- Ключи только объекты\\n\\n- Не итерируемы\\n\\n- Используются для метаданных\\n\\nArrayBuffer и TypedArrays\\n\\n- Бинарные данные\\n\\n- Фиксированная длина\\n\\n- Используются для работы с файлами, сетью\\n\\nСравнение структур\\nObject vs Map\\n\\n- Object: строковые ключи, прототип, JSON-совместимость\\n\\n- Map: любые ключи, порядок сохранения, лучшая производительность для частых изменений\\n\\nArray vs Set\\n\\n- Array: дубликаты разрешены, порядок по индексу, методы для манипуляций\\n\\n- Set: только уникальные значения, быстрый поиск, простые операции\\n\\nВывод: Выбор структуры данных зависит от конкретной задачи - массивы для упорядоченных данных, объекты для структурированной информации, Set для уникальности, Map для сложных ключей.","// Создание и работа с массивом\\nconst fruits = [\'apple\', \'banana\', \'orange\'];\\nfruits.push(\'grape\'); // Добавление элемента\\nfruits.pop(); // Удаление последнего элемента\\n\\n// Методы массива\\nfruits.map(fruit => fruit.toUpperCase());\\nfruits.filter(fruit => fruit.length > 5);\\nfruits.reduce((acc, fruit) => acc + fruit.length, 0);\\n\\n// Создание объекта\\nconst person = {\\n    name: \'John\',\\n    age: 30,\\n    isStudent: false\\n};\\n\\n// Доступ к свойствам\\nconsole.log(person.name); // John\\nperson.city = \'New York\'; // Добавление свойства\\n\\n// Итерация по свойствам\\nfor (let key in person) {\\n    console.log(key, person[key]);\\n}\\n\\n// Работа с Set\\nconst uniqueNumbers = new Set([1, 2, 3, 2, 1]);\\nuniqueNumbers.add(4); // Добавление элемента\\nuniqueNumbers.has(3); // Проверка наличия - true\\nuniqueNumbers.delete(2); // Удаление элемента\\n\\n// Преобразование в массив\\nconst arrayFromSet = Array.from(uniqueNumbers);\\n\\n// Использование Map\\nconst userMap = new Map();\\nuserMap.set(\'id\', 123);\\nuserMap.set(42, \'answer\');\\nuserMap.set({}, \'object key\');\\n\\n// Получение значений\\nconsole.log(userMap.get(\'id\')); // 123\\nconsole.log(userMap.size); // 3\\n\\n// Итерация\\nfor (let [key, value] of userMap) {\\n    console.log(key, value);\\n}"],[1180,"requestAnimationFrame используют для плавной анимации и визуальных обновлений, синхронизированных с частотой обновления экрана. Он обеспечивает оптимальную производительность, автоматически приостанавливая выполнение когда страница не видна, и вызывая колбэк перед перерисовкой браузера.","Определение requestAnimationFrame\\n`requestAnimationFrame` - это браузерный API, который позволяет выполнять код синхронно с обновлением экрана, обычно 60 раз в секунду.\\nОсновные случаи использования\\nСоздание плавной анимации\\njavascript\\n\\nОптимизация частых визуальных обновлений\\njavascript\\n\\nПреимущества перед setTimeout/setInterval\\nСинхронизация с браузером\\n\\n- Автоматическая пауза когда страница неактивна или скрыта\\n\\n- Согласование с частотой обновления экрана (обычно 60fps)\\n\\n- Выполнение перед рендерингом - гарантия актуальности данных\\n\\nСравнение подходов\\njavascript\\n\\nПрактические примеры применения\\nИгровая графика и анимации\\njavascript\\n\\nИзмерение производительности\\njavascript\\n\\nОсобенности работы\\nВремя выполнения колбэка\\njavascript\\n\\nОтмена анимации\\njavascript\\n\\nBest Practices\\nОптимизация производительности\\njavascript\\n\\nБатчинг обновлений\\njavascript\\n\\nВывод: requestAnimationFrame следует использовать для любых визуальных обновлений и анимаций, где важна плавность и производительность. Он обеспечивает оптимальную синхронизацию с браузерным рендерингом и автоматически адаптируется к системным ресурсам.","function animateElement(element) {\\n    let startTime = null;\\n    const duration = 2000; // 2 секунды\\n    \\n    function step(timestamp) {\\n        if (!startTime) startTime = timestamp;\\n        const progress = timestamp - startTime;\\n        \\n        // Вычисление текущей позиции\\n        const translateX = (progress / duration) * 200;\\n        element.style.transform = `translateX(${translateX}px)`;\\n        \\n        // Продолжение анимации\\n        if (progress < duration) {\\n            requestAnimationFrame(step);\\n        }\\n    }\\n    \\n    requestAnimationFrame(step);\\n}\\n\\nclass SmoothScroller {\\n    constructor() {\\n        this.isScrolling = false;\\n        this.targetScroll = 0;\\n    }\\n    \\n    scrollTo(target) {\\n        this.targetScroll = target;\\n        if (!this.isScrolling) {\\n            this.animateScroll();\\n        }\\n    }\\n    \\n    animateScroll() {\\n        this.isScrolling = true;\\n        const currentScroll = window.pageYOffset;\\n        const distance = this.targetScroll - currentScroll;\\n        \\n        if (Math.abs(distance) < 1) {\\n            this.isScrolling = false;\\n            return;\\n        }\\n        \\n        // Плавное замедление\\n        const newScroll = currentScroll + distance * 0.1;\\n        window.scrollTo(0, newScroll);\\n        \\n        requestAnimationFrame(() => this.animateScroll());\\n    }\\n}\\n\\n// Плохо - с setTimeout\\nfunction animateWithTimeout() {\\n    element.style.left = (parseInt(element.style.left) + 1) + \'px\';\\n    setTimeout(animateWithTimeout, 16); // ~60fps\\n}\\n\\n// Хорошо - с requestAnimationFrame\\nfunction animateWithRAF() {\\n    element.style.left = (parseInt(element.style.left) + 1) + \'px\';\\n    requestAnimationFrame(animateWithRAF);\\n}\\n\\nclass GameEngine {\\n    constructor() {\\n        this.lastTime = 0;\\n        this.isRunning = false;\\n    }\\n    \\n    start() {\\n        this.isRunning = true;\\n        this.gameLoop(0);\\n    }\\n    \\n    gameLoop(timestamp) {\\n        if (!this.isRunning) return;\\n        \\n        // Вычисление delta time для независимости от FPS\\n        const deltaTime = timestamp - this.lastTime;\\n        this.lastTime = timestamp;\\n        \\n        // Обновление игрового состояния\\n        this.update(deltaTime);\\n        \\n        // Отрисовка кадра\\n        this.render();\\n        \\n        // Следующий кадр\\n        requestAnimationFrame((time) => this.gameLoop(time));\\n    }\\n    \\n    update(deltaTime) {\\n        // Обновление позиций объектов, физика и т.д.\\n    }\\n    \\n    render() {\\n        // Отрисовка игровых объектов\\n    }\\n    \\n    stop() {\\n        this.isRunning = false;\\n    }\\n}\\n\\nfunction measureFPS() {\\n    let frameCount = 0;\\n    let lastTime = performance.now();\\n    let fps = 0;\\n    \\n    function countFrame() {\\n        frameCount++;\\n        const currentTime = performance.now();\\n        \\n        if (currentTime - lastTime >= 1000) {\\n            fps = frameCount;\\n            frameCount = 0;\\n            lastTime = currentTime;\\n            console.log(`FPS: ${fps}`);\\n        }\\n        \\n        requestAnimationFrame(countFrame);\\n    }\\n    \\n    requestAnimationFrame(countFrame);\\n}\\n\\nrequestAnimationFrame((timestamp) => {\\n    // timestamp - время с момента загрузки страницы в миллисекундах\\n    // Точное время когда будет выполнен рендеринг\\n    console.log(`Кадр будет отрисован в: ${timestamp}`);\\n});\\n\\nlet animationId = null;\\n\\nfunction startAnimation() {\\n    function animate() {\\n        // Логика анимации\\n        animationId = requestAnimationFrame(animate);\\n    }\\n    animationId = requestAnimationFrame(animate);\\n}\\n\\nfunction stopAnimation() {\\n    if (animationId) {\\n        cancelAnimationFrame(animationId);\\n        animationId = null;\\n    }\\n}\\n\\nfunction efficientAnimation() {\\n    let rafId = null;\\n    \\n    function animationStep() {\\n        // Выполняем только необходимые вычисления\\n        performCalculations();\\n        \\n        // Проверяем нужно ли продолжать\\n        if (shouldContinueAnimation()) {\\n            rafId = requestAnimationFrame(animationStep);\\n        } else {\\n            rafId = null;\\n        }\\n    }\\n    \\n    function start() {\\n        if (!rafId) {\\n            rafId = requestAnimationFrame(animationStep);\\n        }\\n    }\\n    \\n    function stop() {\\n        if (rafId) {\\n            cancelAnimationFrame(rafId);\\n            rafId = null;\\n        }\\n    }\\n    \\n    return { start, stop };\\n}\\n\\nclass BatchedAnimator {\\n    constructor() {\\n        this.callbacks = new Set();\\n        this.rafId = null;\\n    }\\n    \\n    addCallback(callback) {\\n        this.callbacks.add(callback);\\n        this.scheduleFrame();\\n    }\\n    \\n    removeCallback(callback) {\\n        this.callbacks.delete(callback);\\n        if (this.callbacks.size === 0 && this.rafId) {\\n            cancelAnimationFrame(this.rafId);\\n            this.rafId = null;\\n        }\\n    }\\n    \\n    scheduleFrame() {\\n        if (!this.rafId) {\\n            this.rafId = requestAnimationFrame(() => {\\n                this.rafId = null;\\n                this.executeCallbacks();\\n            });\\n        }\\n    }\\n    \\n    executeCallbacks() {\\n        this.callbacks.forEach(callback => {\\n            try {\\n                callback();\\n            } catch (error) {\\n                console.error(\'Animation error:\', error);\\n            }\\n        });\\n    }\\n}"],[1181,"Event Loop - это механизм, который позволяет JavaScript обрабатывать асинхронные операции в однопоточном окружении. Он постоянно проверяет очередь задач и выполняет их по порядку. Сначала выполняются все синхронные задачи из call stack, затем микрозадачи (promises), затем макрозадачи (setTimeout, события). Этот цикл обеспечивает неблокирующее выполнение кода.","Основные компоненты Event Loop\\nCall Stack (Стек вызовов)\\n\\n- LIFO-структура (последний вошел - первый вышел)\\n\\n- Хранит выполняемые функции\\n\\n- Один поток выполнения - одна операция в момент времени\\n\\njavascript\\n\\nCallback Queue (Очередь колбэков)\\n\\n- FIFO-структура (первый вошел - первый вышел)\\n\\n- Хранит готовые к выполнению асинхронные колбэки\\n\\n- Макрозадачи: setTimeout, setInterval, UI events\\n\\nMicrotask Queue (Очередь микрозадач)\\n\\n- Приоритет над callback queue\\n\\n- Хранит микрозадачи: Promise then/catch/finally, queueMicrotask\\n\\n- Выполняется полностью после каждого макрозадания\\n\\nПринцип работы Event Loop\\nБазовый цикл\\n\\n- Выполнить синхронный код из call stack\\n\\n- Проверить очередь микрозадач - выполнить все до опустошения\\n\\n- Выполнить одну макрозадачу из callback queue\\n\\n- Повторить с шага 2\\n\\nПрактические примеры\\nПример выполнения\\njavascript\\n\\nПодробный разбор выполнения\\njavascript\\n\\nТипы очередей и их приоритеты\\nОчередь микрозадач (Microtask Queue)\\n\\n- Promise callbacks (.then, .catch, .finally)\\n\\n- queueMicrotask()\\n\\n- MutationObserver (в браузере)\\n\\n- process.nextTick (в Node.js)\\n\\nОчередь макрозадач (Macrotask Queue)\\n\\n- setTimeout, setInterval\\n\\n- setImmediate (Node.js)\\n\\n- I/O операции\\n\\n- UI rendering (браузер)\\n\\n- События (click, load и т.д.)\\n\\nEvent Loop в разных средах\\nБраузер\\n\\n- Несколько очередей для разных типов событий\\n\\n- Render steps - обновление UI между задачами\\n\\n- RequestAnimationFrame - синхронизация с кадрами анимации\\n\\nNode.js\\n\\n- Несколько фаз event loop: timers, pending callbacks, idle/prepare, poll, check, close\\n\\n- process.nextTick - отдельная очередь с высшим приоритетом\\n\\n- setImmediate - выполнение после фазы poll\\n\\nБлокирующие операции\\nПроблемы долгих вычислений\\njavascript\\n\\nBest Practices\\nИзбегание блокировки event loop\\n\\n- Разбивайте тяжелые вычисления на части\\n\\n- Используйте Web Workers для CPU-intensive задач\\n\\n- Применяйте асинхронные операции для I/O\\n\\n- Минимизируйте синхронные операции в циклах\\n\\nПравильное использование Promise\\njavascript\\n\\nВывод: Понимание Event Loop критически важно для написания эффективного и отзывчивого JavaScript-кода. Используйте асинхронные операции для предотвращения блокировки и правильно распределяйте задачи между очередями.","function first() {\\n    second();\\n    console.log(\'First\');\\n}\\n\\nfunction second() {\\n    console.log(\'Second\');\\n}\\n\\nfirst(); // Call stack: first -> second -> console.log\\n\\nconsole.log(\'Start\'); // 1. Синхронный код\\n\\nsetTimeout(() => {\\n    console.log(\'Timeout\'); // 4. Макрозадача\\n}, 0);\\n\\nPromise.resolve().then(() => {\\n    console.log(\'Promise\'); // 3. Микрозадача\\n});\\n\\nconsole.log(\'End\'); // 2. Синхронный код\\n\\n// Результат: Start, End, Promise, Timeout\\n\\n// 1. Синхронная фаза\\nconsole.log(\'Script start\');\\n\\nsetTimeout(function timeout1() {\\n    console.log(\'Timeout 1\');\\n}, 0);\\n\\nPromise.resolve().then(function promise1() {\\n    console.log(\'Promise 1\');\\n});\\n\\nsetTimeout(function timeout2() {\\n    console.log(\'Timeout 2\');\\n    Promise.resolve().then(function promise2() {\\n        console.log(\'Promise 2\');\\n    });\\n}, 0);\\n\\nconsole.log(\'Script end\');\\n\\n/*\\nПорядок выполнения:\\n1. Script start\\n2. Script end\\n3. Promise 1        (микрозадача)\\n4. Timeout 1        (макрозадача)\\n5. Timeout 2        (макрозадача)\\n6. Promise 2        (микрозадача внутри макрозадачи)\\n*/\\n\\n// Плохо - блокирует event loop\\nfunction heavyCalculation() {\\n    let result = 0;\\n    for (let i = 0; i < 1000000000; i++) {\\n        result += Math.sqrt(i);\\n    }\\n    return result;\\n}\\n\\n// Лучше - разбить на части\\nasync function nonBlockingCalculation() {\\n    let result = 0;\\n    const chunkSize = 1000000;\\n    \\n    for (let i = 0; i < 1000000000; i += chunkSize) {\\n        // Позволяет event loop обрабатывать другие задачи\\n        await new Promise(resolve => setTimeout(resolve, 0));\\n        \\n        for (let j = i; j < i + chunkSize; j++) {\\n            result += Math.sqrt(j);\\n        }\\n    }\\n    return result;\\n}\\n\\n// Эффективное создание микрозадач\\nasync function processData(data) {\\n    // Используйте queueMicrotask для приоритетных задач\\n    queueMicrotask(() => {\\n        console.log(\'High priority task\');\\n    });\\n    \\n    // Promise для обычных асинхронных операций\\n    return await fetch(\'/api/process\', {\\n        method: \'POST\',\\n        body: JSON.stringify(data)\\n    });\\n}"],[1182,"Fetch — это встроенный браузерный API для выполнения HTTP-запросов. Axios — сторонняя библиотека, предоставляющая более удобный интерфейс. Axios автоматически обрабатывает JSON и ошибки, Fetch требует больше ручной логики. Axios поддерживает interceptors, Fetch — нет. Выбор зависит от сложности проекта и требований к сетевой логике.","Fetch и Axios решают одну задачу — выполнение HTTP-запросов, но делают это по-разному.\\nFetch\\nFetch — это нативный браузерный API.\\nОсобенности:\\n\\n- Доступен без установки библиотек\\n\\n- Возвращает `Promise`\\n\\n- Не считает HTTP-ошибки (`4xx`, `5xx`) ошибками\\n\\n- Требует ручного парсинга ответа\\n\\nПример типовой логики:\\n\\nAxios\\nAxios — это внешняя библиотека.\\nОсобенности:\\n\\n- Автоматически парсит JSON\\n\\n- Бросает ошибку при `4xx` и `5xx`\\n\\n- Поддерживает interceptors\\n\\n- Удобнее для масштабных приложений\\n\\nПрактическое различие\\nFetch чаще используют:\\n\\n- в небольших проектах\\n\\n- без сложной логики авторизации\\n\\nAxios чаще выбирают:\\n\\n- в SPA\\n\\n- при наличии авторизации\\n\\n- при сложной обработке ошибок\\n\\nВывод:\\nFetch подходит для простых сценариев, Axios — для крупных frontend-приложений с общей сетевой инфраструктурой.","fetch(url)\\n  .then(res => res.json()) // проверка status и парсинг вручную"],[1183,"Call stack — это структура данных, которая хранит информацию о вызовах функций. JavaScript добавляет функции в стек при вызове и удаляет их после завершения. Код выполняется строго сверху вниз, по принципу LIFO. Call stack помогает отслеживать, какая функция выполняется в данный момент. Переполнение стека приводит к ошибке.","Call stack — это механизм, с помощью которого JavaScript отслеживает выполнение кода.\\nКак работает call stack\\nJavaScript выполняет код следующим образом:\\n\\n- Глобальный контекст помещается в стек\\n\\n- При вызове функции создаётся новый контекст\\n\\n- Контекст добавляется в верх стека\\n\\n- После завершения функции контекст удаляется\\n\\nЭтот принцип называется LIFO (Last In, First Out).\\nПример логики выполнения\\n\\nПорядок в стеке:\\n\\n- global\\n\\n- a\\n\\n- b\\n\\n- c\\n\\nПочему call stack важен\\nCall stack:\\n\\n- определяет порядок выполнения кода\\n\\n- объясняет синхронную природу JavaScript\\n\\n- помогает понимать ошибки и stack trace\\n\\nТипичная проблема\\nЕсли функция вызывает сама себя без выхода:\\n\\n- стек переполняется\\n\\n- возникает `Maximum call stack size exceeded`\\n\\nВывод:\\nCall stack — это основа синхронного выполнения JavaScript-кода и ключ к пониманию порядка вызовов функций.","function a() {\\n  b()\\n}\\n\\nfunction b() {\\n  c()\\n}\\n\\nfunction c() {\\n  // выполнение\\n}\\n\\na()"],[1184,"Web APIs — это набор API, предоставляемых браузером, а не JavaScript-движком. Они позволяют работать с таймерами, HTTP-запросами и событиями. Асинхронные операции выполняются вне call stack. После завершения результат возвращается обратно в JavaScript. Это основа асинхронного поведения в браузере.","JavaScript сам по себе не умеет выполнять асинхронные операции — этим занимаются Web APIs, предоставляемые браузером.\\nЧто относится к Web APIs\\nК Web APIs относятся:\\n\\n- `setTimeout`\\n\\n- `fetch`\\n\\n- DOM events\\n\\n- `WebSocket`\\n\\n- `localStorage`\\n\\nКак Web APIs взаимодействуют с JavaScript\\nПроцесс выглядит так:\\n\\n- JavaScript передаёт задачу в Web API\\n\\n- Web API выполняет операцию асинхронно\\n\\n- После завершения callback ставится в очередь\\n\\n- Event Loop возвращает callback в call stack\\n\\nПочему это важно\\nWeb APIs:\\n\\n- разгружают call stack\\n\\n- позволяют выполнять асинхронные операции\\n\\n- делают JavaScript неблокирующим\\n\\nПрактический аспект\\nБез Web APIs:\\n\\n- нельзя было бы делать HTTP-запросы\\n\\n- таймеры блокировали бы выполнение кода\\n\\n- интерфейс зависал бы\\n\\nВывод:\\nWeb APIs — это мост между JavaScript и возможностями браузера, обеспечивающий асинхронную работу приложений.",null],[1185,"Очередь задач — это структура, в которую попадают callbacks асинхронных операций. Event Loop следит за call stack и очередью задач. Когда call stack пуст, Event Loop берёт задачу из очереди и помещает её в стек. Так JavaScript обрабатывает асинхронный код. Это обеспечивает неблокирующее выполнение.","Очередь задач — важная часть механизма Event Loop, отвечающего за асинхронность.\\nЧто такое очередь задач\\nОчередь задач (task queue):\\n\\n- хранит callbacks\\n\\n- ожидает освобождения call stack\\n\\n- работает по принципу FIFO\\n\\nКак задачи попадают в очередь\\nЗадачи добавляются:\\n\\n- после `setTimeout`\\n\\n- после завершения HTTP-запроса\\n\\n- после событий пользователя\\n\\nРоль Event Loop\\nEvent Loop:\\n\\n- Проверяет, пуст ли call stack\\n\\n- Берёт первую задачу из очереди\\n\\n- Перемещает её в call stack\\n\\n- Запускает выполнение\\n\\nПочему это важно для frontend\\nПонимание очереди задач помогает:\\n\\n- объяснить порядок выполнения кода\\n\\n- избегать race conditions\\n\\n- писать предсказуемый асинхронный код\\n\\nВывод:\\nОчередь задач и Event Loop обеспечивают асинхронную модель JavaScript без блокировки основного потока.",null],[1186,"Microtask выполняются раньше macrotask. Сначала выполняется весь синхронный код, затем очищается очередь microtask, и только потом берётся следующая macrotask. `Promise.then` и `queueMicrotask` относятся к microtask, а `setTimeout` — к macrotask. Это влияет на порядок выполнения кода и рендеринг. Понимание порядка помогает правильно писать асинхронную логику.","Event Loop выполняет задачи не просто “по очереди”, а с приоритетом: microtask имеют более высокий приоритет, чем macrotask.\\nЧто относится к microtask и macrotask\\n\\n- Microtask queue\\n\\n- `Promise.then / catch / finally`\\n\\n- `queueMicrotask`\\n\\n- `MutationObserver`\\n\\n- Macrotask queue (task queue)\\n\\n- `setTimeout / setInterval`\\n\\n- события UI (например, `click`)\\n\\n- сетевые события (в упрощённом понимании)\\n\\n- `postMessage` (часто рассматривают как task)\\n\\nПорядок выполнения\\nВ одном “цикле” Event Loop типичный порядок такой:\\n\\n- Выполняется весь синхронный код (пока call stack не станет пустым)\\n\\n- Затем выполняются все microtask, которые накопились\\n\\n- Затем браузер может выполнить рендер (если нужно)\\n\\n- Потом берётся следующая macrotask и цикл повторяется\\n\\nВажно: microtask выполняются до полного опустошения очереди. Если внутри microtask добавить ещё microtask, они тоже будут выполнены в этом же проходе, прежде чем Event Loop перейдёт к macrotask.\\nНебольшой пример\\n\\nОжидаемый порядок:\\n\\n- `start`\\n\\n- `end`\\n\\n- `promise`\\n\\n- `timeout`\\n\\nПрактическое значение во frontend\\n\\n- Если “перегрузить” microtask (например, цепочками `Promise.then`), можно:\\n\\n- откладывать обработку `setTimeout`\\n\\n- задерживать реакцию UI\\n\\n- ухудшить отзывчивость приложения\\n\\nВывод:\\nВ JavaScript после синхронного кода всегда сначала выполняются microtask, и только потом macrotask — это ключ к пониманию порядка выполнения асинхронности.","console.log(\'start\')\\n\\nsetTimeout(() => console.log(\'timeout\'), 0)\\n\\nPromise.resolve().then(() => console.log(\'promise\'))\\n\\nconsole.log(\'end\')"],[1187,"`setTimeout` не гарантирует выполнение callback ровно через указанное время. Он гарантирует, что callback не выполнится раньше, чем пройдёт заданная задержка. После истечения задержки callback попадает в очередь задач и будет выполнен, когда освободится call stack. На фактическое время влияет нагрузка, блокировки и приоритеты очередей. Поэтому таймер часто срабатывает позже.","`setTimeout(fn, ms)` — это таймер с минимальной задержкой, а не “точный будильник”.\\nЧто реально делает setTimeout\\n\\n- Браузер запускает таймер на `ms`\\n\\n- Когда время прошло, callback не запускается сразу\\n\\n- Callback ставится в очередь macrotask\\n\\n- Он выполнится только тогда, когда:\\n\\n- call stack пуст\\n\\n- очередь microtask очищена\\n\\n- Event Loop доберётся до этой задачи\\n\\nПочему “ровно через ms” невозможно гарантировать\\nПричины задержек:\\n\\n- в call stack выполняется длинный синхронный код\\n\\n- много microtask (например, цепочки `Promise.then`)\\n\\n- браузер занят рендером/обработкой событий\\n\\n- вкладка в фоне (браузеры могут троттлить таймеры)\\n\\nМинимальный пример блокировки\\n\\nДаже при `0` callback выполнится после того, как завершится цикл `while`.\\nПрактика\\n\\n- `setTimeout(..., 0)` — это не “сразу”, а “как получится, когда очередь дойдёт”\\n\\n- для точных интервалов (например, анимаций) обычно используют `requestAnimationFrame`\\n\\n- для “периодических задач” с контролем drift — часто пишут собственный планировщик\\n\\nВывод:\\n`setTimeout` гарантирует только минимальную задержку, а фактическое выполнение зависит от очередей и занятости основного потока.","setTimeout(() => console.log(\'timeout\'), 0)\\n\\nconst start = Date.now()\\nwhile (Date.now() - start < 1000) {\\n  // блокируем поток на 1 секунду\\n}"],[1188,"`setTimeout` может выполниться позже, потому что после истечения времени callback попадает в очередь задач и ждёт своей очереди. Если основной поток занят синхронным кодом, выполнение откладывается. Также задержку увеличивают microtask, рендер и обработка событий. В фоне браузер может специально замедлять таймеры. Поэтому задержка может стать заметно больше, чем указанное значение.","Даже если таймер “истёк”, выполнение callback зависит от того, когда Event Loop сможет реально выполнить задачу.\\nОсновные причины задержек\\n\\n- Блокировка основного потока (call stack занят)\\n\\n- длинные циклы\\n\\n- тяжёлые вычисления\\n\\n- синхронные операции, которые долго выполняются\\n\\n- Очередь microtask имеет приоритет\\n\\n- после каждого завершения задачи Event Loop сначала выполняет microtask\\n\\n- большое количество `Promise.then` может “отодвигать” macrotask\\n\\n- Нагрузка: много задач в очереди macrotask\\n\\n- множество таймеров\\n\\n- обработчики событий\\n\\n- другие callbacks, которые накопились\\n\\n- Рендер и работа браузера\\n\\n- браузер может вставлять этапы отрисовки\\n\\n- тяжёлая разметка/стили/paint могут влиять на задержки\\n\\n- Ограничения браузера (throttling)\\n\\n- в неактивных вкладках таймеры часто “тормозятся”\\n\\n- экономия батареи и ресурсов\\n\\nПрактический вывод для разработчика\\n\\n- таймеры не подходят для точной синхронизации\\n\\n- если важна точность, нужно:\\n\\n- измерять реальное время через `Date.now()` / `performance.now()`\\n\\n- учитывать drift и корректировать расписание\\n\\nВывод:\\n`setTimeout` выполняется позже из-за занятости call stack, приоритета microtask, нагрузки на очередь и ограничений браузера — это нормальное поведение Event Loop.",null],[1189,"Примитивные значения в JavaScript сравниваются по значению. Для сравнения чаще всего используют `===`, который учитывает и тип, и значение. Оператор `==` может выполнять неявное приведение типов. Для чисел, строк, boolean и `null`/`undefined` действуют чёткие правила. Понимание различий важно для избежания логических ошибок.","В JavaScript примитивы сравниваются именно по значению, а не по ссылке.\\nКакие типы считаются примитивами\\nК примитивным типам относятся:\\n\\n- `number`\\n\\n- `string`\\n\\n- `boolean`\\n\\n- `null`\\n\\n- `undefined`\\n\\n- `symbol`\\n\\n- `bigint`\\n\\nОператоры сравнения\\n\\n- Строгое сравнение `===`\\n\\n- сравнивает тип и значение\\n\\n- не выполняет приведение типов\\n\\n- является предпочтительным вариантом\\n\\n- Нестрогое сравнение `==`\\n\\n- выполняет приведение типов\\n\\n- может приводить к неожиданным результатам\\n\\nКак происходит сравнение\\nПри использовании `===`:\\n\\n- сначала сравниваются типы\\n\\n- затем значения\\n\\nЕсли типы различаются — результат `false`.\\nПочему это важно во frontend\\n\\n- условные рендеры зависят от сравнений\\n\\n- ошибки в сравнениях приводят к багам UI\\n\\n- `===` делает поведение кода предсказуемым\\n\\nВывод:\\nПримитивы в JavaScript сравниваются по значению, и в большинстве случаев следует использовать строгое сравнение `===`.","1 === 1      // true\\n1 === \'1\'    // false\\n\\n1 == \'1\'     // true\\nnull == undefined // true"],[1190,"Объекты в JavaScript сравниваются по ссылке, а не по содержимому. Даже если два объекта имеют одинаковые поля и значения, они считаются разными, если созданы отдельно. Оператор `===` проверяет, указывают ли переменные на один и тот же объект в памяти. Поэтому сравнение по значению через `===` невозможно. Это фундаментальное свойство языка.","В JavaScript объекты — это ссылочные типы, и именно это определяет поведение сравнения.\\nКак хранятся объекты\\nКогда создаётся объект:\\n\\n- он размещается в памяти\\n\\n- переменная хранит ссылку на него\\n\\n- не само значение, а адрес\\n\\nХотя `a` и `b` выглядят одинаково, они:\\n\\n- созданы отдельно\\n\\n- имеют разные ссылки в памяти\\n\\nКак работает `===` для объектов\\nОператор `===`:\\n\\n- сравнивает ссылки\\n\\n- не анализирует содержимое объекта\\n\\nНо:\\n\\nПочему JavaScript так устроен\\nПричины:\\n\\n- сравнение ссылок выполняется быстро\\n\\n- глубокое сравнение может быть дорогим\\n\\n- язык избегает неявных затрат\\n\\nПрактические последствия\\n\\n- нельзя сравнивать объекты напрямую\\n\\n- изменения объекта видны всем ссылкам\\n\\n- важно учитывать это при работе со state\\n\\nВывод:\\n`===` для объектов проверяет только ссылку в памяти, а не их содержимое, поэтому сравнение по значению не работает.","const a = { x: 1 }\\nconst b = { x: 1 }\\n\\na === b // false\\n\\nconst c = a\\na === c // true"],[1191,"Сравнение объектов по ссылке означает проверку того, указывают ли переменные на один и тот же объект в памяти. Если ссылки совпадают, объекты считаются равными. Если объекты имеют одинаковое содержимое, но разные ссылки, результат будет `false`. Такое поведение характерно для всех ссылочных типов. Это влияет на работу со state и сравнение данных.","Сравнение по ссылке — это проверка идентичности объекта, а не его структуры или значений.\\nЧто такое ссылка\\nСсылка — это:\\n\\n- указатель на объект в памяти\\n\\n- способ доступа к данным\\n\\n- не само значение объекта\\n\\nПример сравнения по ссылке\\n\\nВ этом примере:\\n\\n- `obj1` и `obj2` ссылаются на один объект\\n\\n- `obj3` — отдельный объект с таким же содержимым\\n\\nГде это особенно важно во frontend\\n\\n- при сравнении `props` и `state`\\n\\n- при оптимизации рендеринга\\n\\n- при использовании `useEffect` и `memo`\\n\\nТипичная ошибка\\nОжидать, что:\\n\\nНа практике это всегда `false`.\\nВывод:\\nСравнение объектов по ссылке означает проверку того, один и тот же это объект в памяти или нет, независимо от его содержимого.","const obj1 = { value: 10 }\\nconst obj2 = obj1\\nconst obj3 = { value: 10 }\\n\\nobj1 === obj2 // true\\nobj1 === obj3 // false\\n\\n{ a: 1 } === { a: 1 } // true"],[1192,"Объекты можно сравнивать по значению с помощью ручного сравнения полей, сериализации в JSON или специальных функций глубокого сравнения. Также используют сторонние библиотеки. У каждого способа есть ограничения по точности и производительности. Универсального решения нет. Выбор зависит от структуры данных и задачи.","Так как `===` сравнивает только ссылки, для сравнения объектов по значению используют дополнительные подходы.\\nОсновные способы сравнения\\n\\n- Ручное сравнение полей\\nПодходит для простых и заранее известных структур.\\n\\n- сравниваются конкретные свойства\\n\\n- легко контролировать логику\\n\\nМинусы:\\n\\n- не масштабируется\\n\\n- сложно поддерживать при изменении структуры\\n\\n- Поверхностное сравнение (shallow compare)\\nПроверяются только значения первого уровня вложенности.\\n\\n- часто используется в UI-оптимизациях\\n\\n- не подходит для вложенных объектов\\n\\n- Сериализация через JSON\\nОбъекты преобразуются в строки и сравниваются.\\n\\nМинусы:\\n\\n- порядок ключей важен\\n\\n- не работает с функциями, `undefined`, `Date`\\n\\n- медленно для больших объектов\\n\\n- Глубокое сравнение (deep compare)\\nРекурсивно сравниваются все вложенные поля.\\n\\n- самый точный вариант\\n\\n- самый дорогой по ресурсам\\n\\nПрактический выбор\\n\\n- простая структура → ручное сравнение\\n\\n- плоские данные → shallow compare\\n\\n- сложные данные → deep compare или библиотека\\n\\nВывод:\\nСпособ сравнения объектов по значению выбирается исходя из сложности данных, требований к точности и производительности.","a.x === b.x && a.y === b.y\\n\\nJSON.stringify(a) === JSON.stringify(b)"],[1193,"Глубокое сравнение объектов — это сравнение всех вложенных свойств и значений. Оно проверяет, совпадает ли структура объектов полностью. Для этого используется рекурсия или обход дерева. Такой подход даёт точный результат, но может быть дорогим по производительности. Его используют только там, где это действительно необходимо.","Глубокое сравнение объектов означает проверку не только ссылок или верхнего уровня, а всей структуры данных целиком.\\nКак работает глубокое сравнение\\nАлгоритм обычно:\\n\\n- Сравнивает типы значений\\n\\n- Проверяет примитивы по значению\\n\\n- Для объектов:\\n\\n- сравнивает количество ключей\\n\\n- рекурсивно сравнивает каждое поле\\n\\nУпрощённая логика\\n\\n(Реализация обычно сложнее и учитывает edge-case’ы.)\\nГде применяется глубокое сравнение\\n\\n- сравнение сложных state-объектов\\n\\n- проверка изменений данных\\n\\n- тестирование\\n\\n- кеширование результатов\\n\\nПочему это не default-решение\\nГлубокое сравнение:\\n\\n- требует рекурсии\\n\\n- обходит все вложенные уровни\\n\\n- может быть дорогим для больших объектов\\n\\nВывод:\\nГлубокое сравнение даёт точный результат, но его следует использовать осознанно из-за стоимости по производительности.","function deepEqual(a, b) {\\n  // проверка типов и примитивов\\n  // рекурсивный обход объектов\\n}"],[1194,"Глубокое сравнение может быть медленным, особенно для больших объектов. Оно может зациклиться при наличии циклических ссылок. Также возникают сложности с типами вроде `Date`, `Map`, `Set` и функций. Частое использование deep compare может ухудшить производительность UI. Поэтому его применяют с осторожностью.","Несмотря на точность, глубокое сравнение имеет ряд серьёзных недостатков, особенно во frontend-приложениях.\\nОсновные проблемы глубокого сравнения\\n\\n- Проблемы производительности\\n\\n- обход всех вложенных уровней\\n\\n- высокая стоимость для больших объектов\\n\\n- может замедлять рендеринг\\n\\n- Циклические ссылки\\nОбъекты могут ссылаться друг на друга:\\n\\nБез защиты это приведёт к бесконечной рекурсии.\\n\\n- Сложные типы данных\\nПроблемы возникают с:\\n\\n- `Date`\\n\\n- `Map`, `Set`\\n\\n- `RegExp`\\n\\n- функциями\\n\\nИх нельзя корректно сравнить простым обходом.\\n\\n- Нестабильность ссылок во frontend\\n\\n- новые объекты создаются при каждом рендере\\n\\n- deep compare может всегда возвращать `false`\\n\\n- приводит к лишним обновлениям\\n\\nПрактический подход\\nВо frontend обычно:\\n\\n- избегают глубоких сравнений в runtime\\n\\n- используют иммутабельность\\n\\n- опираются на сравнение по ссылке\\n\\nВывод:\\nГлубокое сравнение — мощный, но опасный инструмент, который может привести к проблемам с производительностью и стабильностью, если использовать его без необходимости.","a.self = a"],[1195,"Да, для сравнения объектов часто используют сторонние библиотеки. Они корректно обрабатывают вложенные структуры и edge-case’ы. Такие библиотеки экономят время и уменьшают количество ошибок. Их применяют, когда ручная реализация слишком сложна. Это особенно актуально для сложных данных.","В реальных проектах разработчики часто используют готовые библиотеки, а не пишут deep compare самостоятельно.\\nПочему используют библиотеки\\nОсновные причины:\\n\\n- корректная обработка сложных типов\\n\\n- защита от циклических ссылок\\n\\n- оптимизация производительности\\n\\n- проверенные и протестированные реализации\\n\\nТипичные сценарии использования\\nБиблиотеки для сравнения объектов применяются:\\n\\n- в тестах (assert’ы на равенство данных)\\n\\n- при сравнении сложных state-объектов\\n\\n- в утилитах кеширования\\n\\n- при работе с конфигурациями\\n\\nПочему не писать самому\\nСамописная реализация:\\n\\n- легко содержит баги\\n\\n- плохо масштабируется\\n\\n- требует поддержки\\n\\nДаже простое сравнение быстро усложняется из-за `Date`, `Map`, `Set`, массивов и вложенных структур.\\nВажное ограничение\\nДаже с библиотекой:\\n\\n- глубокое сравнение остаётся дорогой операцией\\n\\n- его не стоит использовать в горячих местах (рендер, `useEffect`)\\n\\nВывод:\\nСторонние библиотеки оправданы, когда требуется надёжное и универсальное сравнение объектов, но их нужно применять осознанно.",null],[1196,"Frontend-разработчик может проверить API прямо из браузера. Для этого используют `fetch` или Axios в консоли DevTools. Также можно проверять запросы через Network-вкладку. Иногда используют временные UI-заглушки. Эти способы позволяют быстро проверить поведение API.","Postman — не единственный способ проверить работу API, особенно для frontend-разработчика.\\nОсновные способы проверки без Postman\\n\\n- Через браузерную консоль\\n\\n- `fetch`\\n\\n- Axios (если подключён в проекте)\\n\\n- Через Network в DevTools\\n\\n- анализ запросов реального приложения\\n\\n- проверка заголовков и payload\\n\\n- просмотр ошибок и таймингов\\n\\n- Через временный UI\\n\\n- кнопка “проверить API”\\n\\n- простая форма\\n\\n- debug-компоненты\\n\\nПочему это полезно\\n\\n- ближе к реальному поведению приложения\\n\\n- можно сразу проверить интеграцию\\n\\n- не требует внешних инструментов\\n\\nОграничения\\n\\n- сложнее управлять большим количеством запросов\\n\\n- нет удобной истории и коллекций\\n\\nВывод:\\nFrontend-разработчик может эффективно проверять API прямо из браузера, используя DevTools и код приложения.","fetch(\'/api/users\')\\n  .then(res => res.json())\\n  .then(console.log)"],[1197,"Ключевое слово `const` запрещает переопределять ссылку на объект, но не запрещает менять его внутреннее содержимое.\\nЕсли объект объявлен через `const`, вы не можете присвоить ему другой объект, но можете изменять его свойства.\\nЭто связано с тем, что `const` работает на уровне ссылки, а не на уровне структуры данных.\\nПоэтому добавление, изменение или удаление свойств объекта разрешено.","В JavaScript важно понимать, что именно делает `const` и на каком уровне он работает.\\nОпределение\\n`const` — это способ объявления переменной, который запрещает изменение ссылки на значение, но не делает само значение неизменяемым, если это объект.\\nКак это работает\\nКогда вы объявляете объект через `const`, происходит следующее:\\n\\n- В переменную записывается ссылка на объект в памяти\\n\\n- Эта ссылка становится неизменяемой\\n\\n- Сам объект по этой ссылке остаётся изменяемым\\n\\nПочему так сделано\\nJavaScript разделяет:\\n\\n- примитивы (number, string, boolean)\\n\\n- ссылочные типы (object, array, function)\\n\\nДля объектов изменение свойств не требует изменения ссылки, а значит `const` этому не мешает.\\nКак сделать объект действительно неизменяемым\\nЕсли требуется запретить изменение содержимого:\\n\\n- использовать `Object.freeze`\\n\\n- применять иммутабельные подходы\\n\\n- создавать новые объекты вместо изменения существующих\\n\\nКраткий вывод\\n`const` защищает ссылку, а не объект. Для реальной неизменяемости нужно использовать дополнительные механизмы.","const user = { name: \'Alex\' };\\n\\n// Разрешено\\nuser.name = \'Bob\';\\nuser.age = 30;\\n\\n// Ошибка\\nuser = { name: \'John\' };"],[1198,"`Object.assign` делает поверхностное копирование объекта.\\n`JSON.stringify / JSON.parse` выполняет глубокое копирование, но с серьёзными ограничениями.\\nПри использовании JSON теряются функции, `undefined`, `Symbol` и специальные типы данных.\\nТакже JSON не умеет работать с циклическими ссылками.","Оба подхода используются для копирования объектов, но работают принципиально по-разному.\\n`Object.assign`\\nЭтот метод копирует свойства из одного объекта в другой:\\n\\n- копирование происходит только на первом уровне\\n\\n- вложенные объекты копируются по ссылке\\n\\n`JSON.stringify / JSON.parse`\\nЭтот способ работает иначе:\\n\\n- Объект превращается в строку JSON\\n\\n- Затем строка парсится обратно в объект\\n\\nОсобенности:\\n\\n- создаётся новый объект на всех уровнях\\n\\n- это похоже на глубокое копирование\\n\\n- но поддерживаются только JSON-совместимые данные\\n\\nКлючевые отличия подходов\\nПеред использованием важно учитывать:\\n\\n- `Object.assign` быстрее и безопаснее для простых структур\\n\\n- JSON-подход ломается на сложных типах данных\\n\\n- JSON не поддерживает циклические ссылки\\n\\nКраткий вывод\\n`Object.assign` — поверхностное копирование без сюрпризов.\\nJSON-копирование — псевдоглубокое, но с потерей данных и ограничениями.","const original = { a: 1, nested: { b: 2 } };\\nconst copy = Object.assign({}, original);\\n\\ncopy.nested.b = 100;\\n// original.nested.b тоже станет 100\\n\\nconst copy = JSON.parse(JSON.stringify(original));"],[1199,"`JSON.stringify` не умеет работать со всеми типами данных JavaScript.\\nОн удаляет функции, `undefined`, `Symbol` и методы объектов.\\nТакже он не поддерживает циклические ссылки и специальные объекты вроде `Date` или `Map`.\\nИз-за этого результат копирования может отличаться от исходного объекта.","Несмотря на популярность, JSON-копирование имеет много подводных камней.\\nПотеря типов данных\\nПри сериализации теряются:\\n\\n- `function`\\n\\n- `undefined`\\n\\n- `Symbol`\\n\\nПроблемы со специальными объектами\\nНекоторые типы преобразуются некорректно:\\n\\n- `Date` превращается в строку\\n\\n- `Map` и `Set` теряются\\n\\n- `RegExp` становится пустым объектом\\n\\nЦиклические ссылки\\nЕсли объект содержит ссылку сам на себя, возникнет ошибка:\\n\\nПотеря прототипов\\nПосле копирования:\\n\\n- объект теряет свой прототип\\n\\n- методы класса недоступны\\n\\n- объект становится обычным `Object`\\n\\nКогда это критично\\nJSON-копирование опасно, если:\\n\\n- объект содержит бизнес-логику\\n\\n- используются классы или даты\\n\\n- важна точная структура данных\\n\\nКраткий вывод\\n`JSON.stringify` подходит только для простых данных.\\nДля сложных структур лучше использовать специализированные методы копирования.","const obj = {\\n  a: 1,\\n  fn: () => {},\\n  value: undefined\\n};\\n\\n// fn и value исчезнут\\n\\nconst obj = {};\\nobj.self = obj;\\n\\n// TypeError: Converting circular structure to JSON"],[1200,"Поверхностное копирование — это копирование объекта, при котором копируются только его свойства первого уровня.\\nЕсли свойство содержит вложенный объект, копируется не сам объект, а ссылка на него.\\nВ результате исходный и скопированный объект частично разделяют одни и те же данные.\\nИзменения во вложенных объектах будут видны в обеих копиях.","Поверхностное копирование часто используется в JavaScript, но может приводить к неожиданным эффектам, если не понимать его ограничения.\\nОпределение\\nПоверхностное копирование (shallow copy) — это копирование, при котором:\\n\\n- создаётся новый объект\\n\\n- копируются только значения свойств верхнего уровня\\n\\n- вложенные объекты и массивы копируются по ссылке\\n\\nПримеры поверхностного копирования\\nНа практике поверхностное копирование создаётся с помощью:\\n\\n- `Object.assign`\\n\\n- оператора расширения `...`\\n\\n- методов массивов вроде `slice`\\n\\nЧто происходит в памяти\\nПосле копирования:\\n\\n- `original !== copy`\\n\\n- `original.address === copy.address`\\n\\nЭто означает, что вложенный объект общий для обеих структур.\\nКогда это нормально\\nПоверхностное копирование подходит, если:\\n\\n- объект плоский\\n\\n- вложенные структуры не изменяются\\n\\n- используется иммутабельный подход (создание новых вложенных объектов)\\n\\nКраткий вывод\\nПоверхностное копирование создаёт новую оболочку объекта, но не дублирует вложенные структуры. Это быстро, но требует осторожности","const original = {\\n  name: \'Alex\',\\n  address: { city: \'London\' }\\n};\\n\\nconst copy = { ...original };"]]');export{e as default};